export default Object.freeze({"en":{"copyLanguage":"en","name":"Weight loss scenario calculator","title":"Weight loss calculator free | UsefulVerse","description":"Explore a simple weight-goal timeline from your own inputs. Free, private browser math—not a diet plan or body-weight prediction.","intro":"Explore a transparent, simplified energy-balance scenario for a weight goal. It is arithmetic, not a prediction of how your body will respond.","howQuestion":"How does this weight loss calculator work?","howAnswer":"Enter a current weight, a lower goal weight and a daily calorie deficit you already want to examine. The page applies a fixed linear energy-per-weight assumption to show a mathematical scenario. It does not recommend a calorie deficit, create a diet or predict your actual weight change.","privacyQuestion":"Are my weight details uploaded?","privacyAnswer":"No. The calculation runs in this browser and the entered numbers are not sent to a server or saved by this page.","fields":{"currentWeight":"Current weight","targetWeight":"Goal weight","dailyDeficit":"Daily calorie deficit for this scenario (kcal)","unit":"Weight unit","methodNote":"Simplified linear arithmetic only: 7,700 kcal per kg or 3,500 kcal per lb. Real body-weight change is dynamic; this is not a physiological forecast.","healthNote":"This page does not tell you what to eat or how large a deficit to choose. Health, medicines and individual needs matter. Ask a qualified health professional before changing diet or activity; do not use this estimate as medical advice.","sourceNiddk":"Why body-weight change is dynamic:","sourceCdc":"gradual-change information"},"actions":{"calculate":"Calculate scenario","reset":"Reset","example":"Try example","copy":"Copy result","result":"Scenario result","kilograms":"Kilograms (kg)","pounds":"Pounds (lb)","dayUnit":"days","weekUnit":"weeks","kilocalories":"kcal","perWeek":"per week"},"messages":{"copied":"Result copied.","copyUnavailable":"Copy is not available in this browser.","checkInputs":"Enter a positive current weight, a goal no higher than it, and a daily deficit of zero or more.","estimateOnly":"Mathematical scenario only—not a body-weight prediction or diet recommendation.","weightToLose":"Weight difference","energyEquivalent":"Linear energy equivalent","timeline":"Simple linear timeline","weeklyRate":"Implied weekly rate","noDeficitChange":"With a zero entered deficit, this model shows no change and cannot estimate a timeline.","paceNote":"This linear scenario is above the CDC pace often described as gradual for many adults. It is not a recommended target; ask a health professional."},"additionalFaqs":[{"question":"Is this a prediction of how much weight I will lose?","answer":"No. It applies a fixed linear calorie-to-weight assumption. NIDDK explains that body-weight change is dynamic, so this simple arithmetic can overstate longer-term change."},{"question":"What happens when the daily deficit is zero?","answer":"The modeled energy change is zero, so the page reports no modeled weight change and no finite timeline."}]},"es":{"copyLanguage":"es","name":"Calculadora de escenarios de pérdida de peso","title":"Calculadora de perdida de peso gratis | UsefulVerse","description":"Explore una cronología simple de objetivos de peso a partir de sus propios aportes. Matemáticas de navegador privadas y gratuitas, no un plan de dieta ni…","intro":"Explore un escenario de equilibrio energético transparente y simplificado para un objetivo de peso. Es aritmética, no una predicción de cómo responderá tu cuerpo.","howQuestion":"¿Cómo funciona esta calculadora de pérdida de peso?","howAnswer":"Ingrese un peso actual, un peso objetivo más bajo y un déficit de calorías diario que ya desea examinar. La página aplica una suposición lineal fija de energía por peso para mostrar un escenario matemático. No recomienda un déficit de calorías, no crea una dieta ni predice su cambio de peso real.","privacyQuestion":"¿Están subidos los datos de mi peso?","privacyAnswer":"No. El cálculo se ejecuta en este navegador y los números ingresados ​​no se envían a un servidor ni se guardan en esta página.","fields":{"currentWeight":"Peso actual","targetWeight":"Peso objetivo","dailyDeficit":"Déficit calórico diario para este escenario (kcal)","unit":"Unidad de peso","methodNote":"Sólo aritmética lineal simplificada: 7700 kcal por kg o 3500 kcal por libra. El cambio real del peso corporal es dinámico; Este no es un pronóstico fisiológico.","healthNote":"Esta página no le dice qué comer ni qué tamaño de déficit elegir. La salud, los medicamentos y las necesidades individuales son importantes. Consulte con un profesional de la salud calificado antes de cambiar de dieta o actividad; No utilice esta estimación como consejo médico.","sourceNiddk":"Por qué el cambio de peso corporal es dinámico:","sourceCdc":"información de cambio gradual"},"actions":{"calculate":"Calcular escenario","reset":"Restablecer","example":"Ejemplo de prueba","copy":"Copiar resultado","result":"Resultado del escenario","kilograms":"Kilogramos (kg)","pounds":"Libras (lb)","dayUnit":"días","weekUnit":"semanas","kilocalories":"kcal","perWeek":"por semana"},"messages":{"copied":"Resultado copiado.","copyUnavailable":"La copia no está disponible en este navegador.","checkInputs":"Introduzca un peso actual positivo, una meta no superior a él y un déficit diario de cero o más.","estimateOnly":"Escenario matemático únicamente, no una predicción del peso corporal ni una recomendación de dieta.","weightToLose":"Diferencia de peso","energyEquivalent":"Equivalente de energía lineal","timeline":"Línea de tiempo lineal simple","weeklyRate":"Tasa semanal implícita","noDeficitChange":"Con un déficit ingresado de cero, este modelo no muestra cambios y no puede estimar un cronograma.","paceNote":"Este escenario lineal está por encima del ritmo de los CDC que a menudo se describe como gradual para muchos adultos. No es un objetivo recomendado; Pregúntale a un profesional de la salud."},"additionalFaqs":[{"question":"¿Es esta una predicción de cuánto peso perderé?","answer":"No. Aplica una suposición lineal fija de relación calorías-peso. NIDDK explica que el cambio de peso corporal es dinámico, por lo que esta simple aritmética puede exagerar el cambio a largo plazo."},{"question":"¿Qué pasa cuando el déficit diario es cero?","answer":"El cambio de energía modelado es cero, por lo que la página no informa ningún cambio de peso modelado ni una línea de tiempo finita."}]},"fr":{"copyLanguage":"fr","name":"Calculateur de scénario de perte de poids","title":"Calculateur de perte de poids gratuit | UsefulVerse","description":"Explorez une chronologie simple d'objectif de poids à partir de vos propres entrées. Mathématiques gratuites et privées sur navigateur : il ne s'agit pas…","intro":"Explorez un scénario de bilan énergétique transparent et simplifié pour un objectif de poids. Il s’agit d’arithmétique et non de prédiction de la réaction de votre corps.","howQuestion":"Comment fonctionne ce calculateur de perte de poids ?","howAnswer":"Saisissez un poids actuel, un objectif de poids inférieur et un déficit calorique quotidien que vous souhaitez déjà examiner. La page applique une hypothèse d'énergie linéaire fixe par poids pour montrer un scénario mathématique. Il ne recommande pas de déficit calorique, ne crée pas de régime et ne prédit pas votre changement de poids réel.","privacyQuestion":"Mes informations de poids sont-elles téléchargées ?","privacyAnswer":"Non. Le calcul s'exécute dans ce navigateur et les nombres saisis ne sont pas envoyés à un serveur ni enregistrés par cette page.","fields":{"currentWeight":"Poids actuel","targetWeight":"Poids du but","dailyDeficit":"Déficit calorique quotidien pour ce scénario (kcal)","unit":"Unité de poids","methodNote":"Arithmétique linéaire simplifiée uniquement : 7 700 kcal par kg ou 3 500 kcal par livre. Le changement réel du poids corporel est dynamique ; ce n'est pas une prévision physiologique.","healthNote":"Cette page ne vous dit pas quoi manger ni quelle est l'ampleur du déficit choisir. La santé, les médicaments et les besoins individuels comptent. Renseignez-vous auprès d'un professionnel de santé qualifié avant de modifier un régime alimentaire ou une activité ; n’utilisez pas cette estimation comme avis médical.","sourceNiddk":"Pourquoi le changement de poids corporel est dynamique :","sourceCdc":"informations à changement progressif"},"actions":{"calculate":"Calculer le scénario","reset":"Réinitialiser","example":"Essayez l'exemple","copy":"Copier le résultat","result":"Résultat du scénario","kilograms":"Kilogrammes (kg)","pounds":"Livres (lb)","dayUnit":"jours","weekUnit":"semaines","kilocalories":"calories","perWeek":"par semaine"},"messages":{"copied":"Résultat copié.","copyUnavailable":"La copie n'est pas disponible dans ce navigateur.","checkInputs":"Entrez un poids actuel positif, un objectif qui ne dépasse pas celui-ci et un déficit quotidien de zéro ou plus.","estimateOnly":"Scénario mathématique uniquement : il ne s'agit pas d'une prévision du poids corporel ni d'une recommandation alimentaire.","weightToLose":"Différence de poids","energyEquivalent":"Equivalent énergétique linéaire","timeline":"Chronologie linéaire simple","weeklyRate":"Tarif hebdomadaire implicite","noDeficitChange":"Avec un déficit nul, ce modèle ne montre aucun changement et ne peut pas estimer un calendrier.","paceNote":"Ce scénario linéaire est supérieur au rythme du CDC souvent décrit comme progressif pour de nombreux adultes. Ce n'est pas un objectif recommandé ; demandez à un professionnel de la santé."},"additionalFaqs":[{"question":"Est-ce une prédiction de la quantité de poids que je vais perdre ?","answer":"Non. Il applique une hypothèse linéaire fixe de calories par rapport au poids. Le NIDDK explique que le changement de poids corporel est dynamique, de sorte que cette simple arithmétique peut surestimer le changement à long terme."},{"question":"Que se passe-t-il lorsque le déficit journalier est nul ?","answer":"Le changement d'énergie modélisé est nul, donc la page ne rapporte aucun changement de poids modélisé ni aucun calendrier fini."}]},"pt":{"copyLanguage":"pt","name":"Calculadora de cenário de perda de peso","title":"Calculadora de perda de peso grátis | UsefulVerse","description":"Explore um cronograma simples de meta de peso a partir de suas próprias informações. Matemática de navegador privada e gratuita - não um plano de dieta ou…","intro":"Explore um cenário de equilíbrio energético transparente e simplificado para uma meta de peso. É aritmética, não uma previsão de como seu corpo responderá.","howQuestion":"Como funciona esta calculadora de perda de peso?","howAnswer":"Insira um peso atual, uma meta de peso inferior e um déficit calórico diário que você já deseja examinar. A página aplica uma suposição linear fixa de energia por peso para mostrar um cenário matemático. Não recomenda um déficit calórico, não cria uma dieta ou prevê sua mudança real de peso.","privacyQuestion":"Os detalhes do meu peso foram carregados?","privacyAnswer":"Não. O cálculo é executado neste navegador e os números inseridos não são enviados para um servidor ou salvos por esta página.","fields":{"currentWeight":"Peso atual","targetWeight":"Meta de peso","dailyDeficit":"Déficit calórico diário para este cenário (kcal)","unit":"Unidade de peso","methodNote":"Apenas aritmética linear simplificada: 7.700 kcal por kg ou 3.500 kcal por lb. A mudança real do peso corporal é dinâmica; esta não é uma previsão fisiológica.","healthNote":"Esta página não informa o que comer ou qual o tamanho do déficit a ser escolhido. Saúde, medicamentos e necessidades individuais são importantes. Consulte um profissional de saúde qualificado antes de mudar de dieta ou atividade; não use esta estimativa como conselho médico.","sourceNiddk":"Por que a mudança no peso corporal é dinâmica:","sourceCdc":"informações de mudança gradual"},"actions":{"calculate":"Calcular cenário","reset":"Redefinir","example":"Experimente um exemplo","copy":"Copiar resultado","result":"Resultado do cenário","kilograms":"Quilogramas (kg)","pounds":"Libras (lb)","dayUnit":"dias","weekUnit":"semanas","kilocalories":"kcal","perWeek":"por semana"},"messages":{"copied":"Resultado copiado.","copyUnavailable":"A cópia não está disponível neste navegador.","checkInputs":"Insira um peso atual positivo, uma meta não superior a ele e um déficit diário de zero ou mais.","estimateOnly":"Apenas cenário matemático – não uma previsão de peso corporal ou recomendação de dieta.","weightToLose":"Diferença de peso","energyEquivalent":"Energia linear equivalente","timeline":"Linha do tempo linear simples","weeklyRate":"Taxa semanal implícita","noDeficitChange":"Com um déficit inserido zero, este modelo não mostra nenhuma mudança e não pode estimar um cronograma.","paceNote":"Este cenário linear está acima do ritmo do CDC, frequentemente descrito como gradual para muitos adultos. Não é um alvo recomendado; pergunte a um profissional de saúde."},"additionalFaqs":[{"question":"Isso é uma previsão de quanto peso vou perder?","answer":"Não. Aplica uma suposição linear fixa de calorias por peso. O NIDDK explica que a mudança no peso corporal é dinâmica, portanto esta simples aritmética pode exagerar a mudança a longo prazo."},{"question":"O que acontece quando o déficit diário é zero?","answer":"A alteração de energia modelada é zero, portanto a página não relata nenhuma alteração de peso modelada e nenhum cronograma finito."}]},"de":{"copyLanguage":"de","name":"Gewichtsverlust-Szenario-Rechner","title":"Gewichtsverlustrechner kostenlos | UsefulVerse","description":"Erkunden Sie anhand Ihrer eigenen Eingaben eine einfache Gewichtsziel-Zeitleiste. Kostenlose, private Browser-Mathematik – kein Diätplan oder…","intro":"Entdecken Sie ein transparentes, vereinfachtes Energiebilanzszenario für ein Gewichtsziel. Es ist eine Arithmetik und keine Vorhersage darüber, wie Ihr Körper reagieren wird.","howQuestion":"Wie funktioniert dieser Gewichtsverlustrechner?","howAnswer":"Geben Sie ein aktuelles Gewicht, ein niedrigeres Zielgewicht und ein tägliches Kaloriendefizit ein, das Sie bereits überprüfen möchten. Die Seite wendet eine feste lineare Energie-pro-Gewicht-Annahme an, um ein mathematisches Szenario darzustellen. Es wird kein Kaloriendefizit empfohlen, keine Diät erstellt oder die tatsächliche Gewichtsveränderung vorhergesagt.","privacyQuestion":"Werden meine Gewichtsangaben hochgeladen?","privacyAnswer":"Nein. Die Berechnung läuft in diesem Browser und die eingegebenen Zahlen werden nicht an einen Server gesendet oder von dieser Seite gespeichert.","fields":{"currentWeight":"Aktuelles Gewicht","targetWeight":"Zielgewicht","dailyDeficit":"Tägliches Kaloriendefizit für dieses Szenario (kcal)","unit":"Gewichtseinheit","methodNote":"Nur vereinfachte lineare Arithmetik: 7.700 kcal pro kg oder 3.500 kcal pro Pfund. Die tatsächliche Änderung des Körpergewichts ist dynamisch; Dies ist keine physiologische Prognose.","healthNote":"Auf dieser Seite erfahren Sie nicht, was Sie essen oder wie hoch das Defizit sein soll. Gesundheit, Medikamente und individuelle Bedürfnisse sind wichtig. Fragen Sie einen qualifizierten Arzt, bevor Sie Ihre Ernährung oder Aktivität ändern. Verwenden Sie diese Schätzung nicht als medizinischen Rat.","sourceNiddk":"Warum die Veränderung des Körpergewichts dynamisch ist:","sourceCdc":"Informationen zur schrittweisen Änderung"},"actions":{"calculate":"Szenario berechnen","reset":"Zurücksetzen","example":"Beispiel ausprobieren","copy":"Ergebnis kopieren","result":"Szenarioergebnis","kilograms":"Kilogramm (kg)","pounds":"Pfund (lb)","dayUnit":"Tage","weekUnit":"Wochen","kilocalories":"kcal","perWeek":"pro Woche"},"messages":{"copied":"Ergebnis kopiert.","copyUnavailable":"Kopieren ist in diesem Browser nicht verfügbar.","checkInputs":"Geben Sie ein positives aktuelles Gewicht, ein Ziel, das nicht höher ist, und ein tägliches Defizit von null oder mehr ein.","estimateOnly":"Nur mathematisches Szenario – keine Vorhersage des Körpergewichts oder Diätempfehlung.","weightToLose":"Gewichtsunterschied","energyEquivalent":"Lineares Energieäquivalent","timeline":"Einfache lineare Zeitleiste","weeklyRate":"Impliziter Wochenpreis","noDeficitChange":"Bei einem eingegebenen Defizit von Null zeigt dieses Modell keine Veränderung und kann keinen Zeitplan abschätzen.","paceNote":"Dieses lineare Szenario liegt über dem CDC-Tempo, das für viele Erwachsene oft als allmählich beschrieben wird. Es handelt sich nicht um ein empfohlenes Ziel; Fragen Sie einen Arzt."},"additionalFaqs":[{"question":"Ist das eine Vorhersage, wie viel Gewicht ich verlieren werde?","answer":"Nein. Es wird eine feste lineare Kalorien-zu-Gewicht-Annahme angewendet. NIDDK erklärt, dass die Veränderung des Körpergewichts dynamisch ist, sodass diese einfache Arithmetik längerfristige Veränderungen überbewerten kann."},{"question":"Was passiert, wenn das tägliche Defizit Null ist?","answer":"Die modellierte Energieänderung ist Null, daher meldet die Seite keine modellierte Gewichtsänderung und keine endliche Zeitachse."}]},"ja":{"copyLanguage":"ja","name":"減量シナリオ計算機","title":"減量計算機無料 | UsefulVerse","description":"自分自身の入力からシンプルな体重目標タイムラインを探索します。 ダイエット計画や体重予測ではなく、無料のプライベート ブラウザー計算です。","intro":"体重目標に向けた、透明で簡素化されたエネルギー バランス シナリオを検討します。 これは算術的なものであり、身体がどのように反応するかを予測するものではありません。","howQuestion":"この減量計算機はどのように機能しますか?","howAnswer":"すでに調査したい現在の体重、下限目標体重、および 1 日のカロリー不足量を入力します。 このページでは、重量あたりの線形エネルギーの固定仮定を適用して、数学的シナリオを示します。 カロリー不足を推奨したり、食事療法を考案したり、実際の体重変化を予測したりするものではありません。","privacyQuestion":"私の体重の詳細はアップロードされていますか?","privacyAnswer":"いいえ。計算はこのブラウザで実行され、入力された数値はサーバーに送信されたり、このページに保存されたりしません。","fields":{"currentWeight":"現在の体重","targetWeight":"目標体重","dailyDeficit":"このシナリオの 1 日のカロリー不足 (kcal)","unit":"重量単位","methodNote":"単純化された線形演算のみ: 7,700 kcal/kg または 3,500 kcal/lb。実際の体重変化は動的です。 これは生理学的予測ではありません。","healthNote":"このページでは、何を食べるべきか、どれくらいの赤字を選択すべきかについては説明しません。 健康、薬、個人のニーズは重要です。 食事や活動を変更する前に、資格のある医療専門家に相談してください。 この推定値を医学的アドバイスとして使用しないでください。","sourceNiddk":"体重変化が動的である理由:","sourceCdc":"段階的変更情報"},"actions":{"calculate":"シナリオを計算する","reset":"リセット","example":"試してみる例","copy":"コピー結果","result":"シナリオ結果","kilograms":"キログラム (kg)","pounds":"ポンド (lb)","dayUnit":"日","weekUnit":"週間","kilocalories":"kcal","perWeek":"/週"},"messages":{"copied":"結果がコピーされました。","copyUnavailable":"このブラウザではコピーを利用できません。","checkInputs":"正の現在の体重、それを超えない目標、およびゼロ以上の 1 日の不足額を入力します。","estimateOnly":"数学的シナリオのみであり、体重の予測や食事の推奨ではありません。","weightToLose":"体重差","energyEquivalent":"線形エネルギー等価","timeline":"シンプルな線形タイムライン","weeklyRate":"暗黙の週次レート","noDeficitChange":"赤字がゼロの場合、このモデルは変化を示さず、タイムラインを推定できません。","paceNote":"この直線的なシナリオは、多くの成人にとって緩やかであるとよく言われる CDC のペースを上回っています。 これは推奨されるターゲットではありません。 医療専門家に尋ねてください。"},"additionalFaqs":[{"question":"これはどれくらい体重が減るかを予測したものですか?","answer":"いいえ。これは、カロリー対体重の固定線形仮定を適用します。 NIDDK は、体重の変化は動的であるため、この単純な計算では長期的な変化が誇張される可能性があると説明しています。"},{"question":"1 日の赤字がゼロになるとどうなりますか?","answer":"モデル化されたエネルギー変化はゼロであるため、このページにはモデル化された重量変化も有限のタイムラインも報告されません。"}]},"ko":{"copyLanguage":"ko","name":"체중 감량 시나리오 계산기","title":"체중 감량 계산기 무료 | UsefulVerse","description":"자신이 입력한 내용을 바탕으로 간단한 체중-목표 타임라인을 살펴보세요. 무료 비공개 브라우저 수학 – 다이어트 계획이나 체중 예측이 아닙니다.","intro":"체중 목표를 위한 투명하고 단순화된 에너지 균형 시나리오를 살펴보세요. 이는 산술적인 계산이지 신체가 어떻게 반응할지 예측하는 것이 아닙니다.","howQuestion":"이 체중 감량 계산기는 어떻게 작동하나요?","howAnswer":"현재 체중, 더 낮은 목표 체중, 이미 조사하고 싶은 일일 칼로리 적자를 입력하세요. 이 페이지는 수학적 시나리오를 보여주기 위해 고정된 선형 중량당 에너지 가정을 적용합니다. 칼로리 결핍을 권장하지 않으며, 식단을 만들거나 실제 체중 변화를 예측하지 않습니다.","privacyQuestion":"내 체중 정보가 업로드되나요?","privacyAnswer":"아니요. 계산은 이 브라우저에서 실행되며 입력된 숫자는 서버로 전송되거나 이 페이지에 저장되지 않습니다.","fields":{"currentWeight":"현재 무게","targetWeight":"목표 중량","dailyDeficit":"이 시나리오의 일일 칼로리 적자(kcal)","unit":"중량 단위","methodNote":"단순화된 선형 산술만: kg당 7,700kcal 또는 lb당 3,500kcal. 실제 체중 변화는 동적입니다. 이것은 생리학적 예측이 아닙니다.","healthNote":"이 페이지에서는 무엇을 먹어야 할지, 얼마나 많은 적자를 선택해야 할지 알려주지 않습니다. 건강, 의약품 및 개인의 필요가 중요합니다. 식단이나 활동을 바꾸기 전에 자격을 갖춘 의료 전문가에게 문의하십시오. 이 추정치를 의학적 조언으로 사용하지 마십시오.","sourceNiddk":"체중 변화가 역동적인 이유:","sourceCdc":"점진적 변화 정보"},"actions":{"calculate":"시나리오","reset":"계산","example":"재설정 예제","copy":"사용해 보기 결과 복사","result":"시나리오 결과","kilograms":"킬로그램(kg)","pounds":"파운드(lb)","dayUnit":"일","weekUnit":"주","kilocalories":"kcal","perWeek":"주당"},"messages":{"copied":"결과가 복사되었습니다.","copyUnavailable":"이 브라우저에서는 복사할 수 없습니다.","checkInputs":"양의 현재 체중, 목표는 그보다 높지 않고 일일 적자는 0 이상을 입력합니다.","estimateOnly":"수학적 시나리오일 뿐이며 체중 예측이나 다이어트 권장 사항은 아닙니다.","weightToLose":"무게 차이","energyEquivalent":"선형 에너지 등가","timeline":"간단한 선형 타임라인","weeklyRate":"내재 주간 요율","noDeficitChange":"적자가 0으로 입력되면 이 모델은 변화가 없으며 타임라인을 추정할 수 없습니다.","paceNote":"이 선형 시나리오는 많은 성인에게 점진적이라고 종종 설명되는 CDC 속도보다 높습니다. 권장되는 대상은 아닙니다. 건강 전문가에게 물어보세요."},"additionalFaqs":[{"question":"이것은 내가 얼마나 많은 체중을 감량할지 예측하는 것입니까?","answer":"아니요. 고정된 선형 칼로리-체중 가정을 적용합니다. NIDDK는 체중 변화가 역동적이므로 이 간단한 산술이 장기적인 변화를 과장할 수 있다고 설명합니다."},{"question":"일일 적자가 0이면 어떻게 되나요?","answer":"모델링된 에너지 변화는 0이므로 페이지는 모델링된 중량 변화와 유한한 타임라인을 보고하지 않습니다."}]},"id":{"copyLanguage":"id","name":"Kalkulator skenario penurunan berat badan","title":"Kalkulator penurunan berat badan gratis | UsefulVerse","description":"Jelajahi garis waktu sasaran berat badan sederhana dari masukan Anda sendiri. Matematika browser pribadi gratis—bukan rencana diet atau prediksi berat badan.","intro":"Jelajahi skenario keseimbangan energi yang transparan dan disederhanakan untuk mencapai sasaran berat badan. Ini adalah aritmatika, bukan prediksi bagaimana tubuh Anda akan merespons.","howQuestion":"Bagaimana cara kerja kalkulator penurunan berat badan ini?","howAnswer":"Masukkan berat badan saat ini, target berat badan yang lebih rendah, dan defisit kalori harian yang ingin Anda periksa. Halaman ini menerapkan asumsi energi per berat linier tetap untuk menunjukkan skenario matematis. Itu tidak merekomendasikan defisit kalori, membuat pola makan atau memprediksi perubahan berat badan Anda yang sebenarnya.","privacyQuestion":"Apakah rincian berat badan saya diunggah?","privacyAnswer":"Tidak. Perhitungan berjalan di browser ini dan angka yang dimasukkan tidak dikirim ke server atau disimpan oleh halaman ini.","fields":{"currentWeight":"Berat saat ini","targetWeight":"Berat sasaran","dailyDeficit":"Defisit kalori harian untuk skenario ini (kkal)","unit":"Satuan berat","methodNote":"Hanya aritmatika linier yang disederhanakan: 7.700 kkal per kg atau 3.500 kkal per pon. Perubahan berat badan sebenarnya bersifat dinamis; ini bukan prognosis fisiologis.","healthNote":"Halaman ini tidak memberi tahu Anda apa yang harus dimakan atau seberapa besar defisit yang harus dipilih. Kesehatan, obat-obatan dan kebutuhan individu penting. Tanyakan kepada ahli kesehatan yang berkualifikasi sebelum mengubah pola makan atau aktivitas; jangan gunakan perkiraan ini sebagai nasihat medis.","sourceNiddk":"Mengapa perubahan berat badan bersifat dinamis:","sourceCdc":"informasi perubahan bertahap"},"actions":{"calculate":"Hitung skenario","reset":"Setel ulang","example":"Coba contoh","copy":"Salin hasil","result":"Hasil skenario","kilograms":"Kilogram (kg)","pounds":"Pound (lb)","dayUnit":"hari","weekUnit":"minggu","kilocalories":"kkal","perWeek":"per minggu"},"messages":{"copied":"Hasil disalin.","copyUnavailable":"Salinan tidak tersedia di browser ini.","checkInputs":"Masukkan bobot positif saat ini, sasaran tidak lebih tinggi dari itu, dan defisit harian sebesar nol atau lebih.","estimateOnly":"Hanya skenario matematis—bukan prediksi berat badan atau rekomendasi diet.","weightToLose":"Perbedaan berat","energyEquivalent":"Setara energi linier","timeline":"Garis waktu linier sederhana","weeklyRate":"Tarif mingguan tersirat","noDeficitChange":"Dengan defisit yang dimasukkan nol, model ini tidak menunjukkan perubahan dan tidak dapat memperkirakan jangka waktu.","paceNote":"Skenario linier ini berada di atas kecepatan CDC yang sering digambarkan sebagai skenario bertahap bagi banyak orang dewasa. Ini bukanlah target yang direkomendasikan; tanyakan pada ahli kesehatan."},"additionalFaqs":[{"question":"Apakah ini prediksi berapa berat badan saya yang akan turun?","answer":"Tidak. Ini menerapkan asumsi kalori-terhadap-berat yang linier dan tetap. NIDDK menjelaskan bahwa perubahan berat badan bersifat dinamis, sehingga perhitungan sederhana ini dapat melebih-lebihkan perubahan jangka panjang."},{"question":"Apa yang terjadi jika defisit harian nol?","answer":"Perubahan energi yang dimodelkan adalah nol, sehingga halaman tersebut melaporkan tidak ada perubahan berat yang dimodelkan dan tidak ada garis waktu yang terbatas."}]},"hi":{"copyLanguage":"hi","name":"वजन घटाने का परिदृश्य कैलकुलेटर","title":"वज़न घटाने का कैलकुलेटर निःशुल्क | UsefulVerse","description":"अपने स्वयं के इनपुट से एक सरल वजन-लक्ष्य समयरेखा का अन्वेषण करें। नि:शुल्क, निजी ब्राउज़र गणित—कोई आहार योजना या शरीर-वजन की भविष्यवाणी नहीं।","intro":"वज़न लक्ष्य के लिए पारदर्शी, सरलीकृत ऊर्जा-संतुलन परिदृश्य का अन्वेषण करें। यह अंकगणित है, कोई भविष्यवाणी नहीं कि आपका शरीर कैसे प्रतिक्रिया देगा।","howQuestion":"यह वज़न घटाने वाला कैलकुलेटर कैसे काम करता है?","howAnswer":"वर्तमान वजन, कम लक्ष्य वजन और दैनिक कैलोरी घाटा दर्ज करें जिसे आप पहले से ही जांचना चाहते हैं। गणितीय परिदृश्य दिखाने के लिए पृष्ठ एक निश्चित रैखिक ऊर्जा-प्रति-भार धारणा लागू करता है। यह कैलोरी की कमी करने, आहार बनाने या आपके वास्तविक वजन में परिवर्तन की भविष्यवाणी करने की अनुशंसा नहीं करता है।","privacyQuestion":"क्या मेरा वजन विवरण अपलोड किया गया है?","privacyAnswer":"नहीं, गणना इस ब्राउज़र में चलती है और दर्ज किए गए नंबर सर्वर पर नहीं भेजे जाते हैं या इस पृष्ठ द्वारा सहेजे नहीं जाते हैं।","fields":{"currentWeight":"वर्तमान वजन","targetWeight":"लक्ष्य भार","dailyDeficit":"इस परिदृश्य के लिए दैनिक कैलोरी घाटा (किलो कैलोरी)","unit":"वजन इकाई","methodNote":"केवल सरलीकृत रैखिक अंकगणित: 7,700 किलो कैलोरी प्रति किग्रा या 3,500 किलो कैलोरी प्रति पाउंड। वास्तविक शरीर-वजन परिवर्तन गतिशील है; यह कोई शारीरिक पूर्वानुमान नहीं है.","healthNote":"यह पृष्ठ आपको यह नहीं बताता कि क्या खाना चाहिए या कितना बड़ा घाटा चुनना चाहिए। स्वास्थ्य, दवाएँ और व्यक्तिगत ज़रूरतें मायने रखती हैं। आहार या गतिविधि बदलने से पहले किसी योग्य स्वास्थ्य पेशेवर से पूछें; इस अनुमान का उपयोग चिकित्सीय सलाह के रूप में न करें।","sourceNiddk":"शरीर के वजन में परिवर्तन गतिशील क्यों है:","sourceCdc":"क्रमिक-परिवर्तन जानकारी"},"actions":{"calculate":"परिदृश्य","reset":"की गणना करें","example":"को रीसेट करें उदाहरण","copy":"आज़माएँ परिणाम","result":"परिदृश्य परिणाम","kilograms":"किलोग्राम (किग्रा)","pounds":"पाउंड (पौंड)","dayUnit":"दिन","weekUnit":"सप्ताह","kilocalories":"kcal","perWeek":"प्रति सप्ताह"},"messages":{"copied":"परिणाम कॉपी किया गया.","copyUnavailable":"इस ब्राउज़र में प्रतिलिपि उपलब्ध नहीं है.","checkInputs":"एक सकारात्मक वर्तमान भार दर्ज करें, एक लक्ष्य इससे अधिक न हो, और शून्य या अधिक का दैनिक घाटा दर्ज करें।","estimateOnly":"केवल गणितीय परिदृश्य—शरीर-वजन की भविष्यवाणी या आहार अनुशंसा नहीं।","weightToLose":"वज़न में अंतर","energyEquivalent":"रैखिक ऊर्जा समतुल्य","timeline":"सरल रैखिक समयरेखा","weeklyRate":"निहित साप्ताहिक दर","noDeficitChange":"शून्य दर्ज घाटे के साथ, यह मॉडल कोई परिवर्तन नहीं दिखाता है और समयरेखा का अनुमान नहीं लगा सकता है।","paceNote":"यह रैखिक परिदृश्य सीडीसी गति से ऊपर है जिसे अक्सर कई वयस्कों के लिए क्रमिक बताया जाता है। यह अनुशंसित लक्ष्य नहीं है; किसी स्वास्थ्य पेशेवर से पूछें."},"additionalFaqs":[{"question":"क्या यह भविष्यवाणी है कि मैं कितना वजन कम करूंगा?","answer":"नहीं, यह एक निश्चित रैखिक कैलोरी-से-वजन धारणा लागू करता है। एनआईडीडीके बताता है कि शरीर के वजन में परिवर्तन गतिशील है, इसलिए यह सरल अंकगणित दीर्घकालिक परिवर्तन को बढ़ा-चढ़ाकर बता सकता है।"},{"question":"क्या होता है जब दैनिक घाटा शून्य होता है?","answer":"मॉडल किया गया ऊर्जा परिवर्तन शून्य है, इसलिए पृष्ठ कोई मॉडल किए गए वजन परिवर्तन और कोई सीमित समयरेखा की रिपोर्ट नहीं करता है।"}]},"ar":{"copyLanguage":"ar","name":"حاسبة سيناريو فقدان الوزن","title":"حاسبة فقدان الوزن مجانا | UsefulVerse","description":"استكشف جدولًا زمنيًا بسيطًا للوزن والهدف من مدخلاتك الخاصة. حسابات متصفح خاصة ومجانية، وليست خطة نظام غذائي أو توقع وزن الجسم.","intro":"استكشف سيناريو شفاف ومبسط لتوازن الطاقة لتحقيق هدف الوزن. إنها عملية حسابية وليست تنبؤًا بكيفية استجابة جسمك.","howQuestion":"كيف تعمل حاسبة فقدان الوزن هذه؟","howAnswer":"أدخل الوزن الحالي والوزن المستهدف الأقل والعجز اليومي في السعرات الحرارية الذي تريد فحصه بالفعل. تطبق الصفحة افتراضًا خطيًا ثابتًا للطاقة لكل وزن لإظهار سيناريو رياضي. لا ينصح بنقص السعرات الحرارية أو إنشاء نظام غذائي أو التنبؤ بالتغير الفعلي في وزنك.","privacyQuestion":"هل تم تحميل تفاصيل وزني؟","privacyAnswer":"لا، يتم تشغيل الحساب في هذا المتصفح ولا يتم إرسال الأرقام المدخلة إلى الخادم أو حفظها بواسطة هذه الصفحة.","fields":{"currentWeight":"الوزن الحالي","targetWeight":"الوزن المستهدف","dailyDeficit":"العجز اليومي في السعرات الحرارية لهذا السيناريو (سعر حراري)","unit":"وحدة الوزن","methodNote":"الحساب الخطي المبسط فقط: 7700 سعرة حرارية لكل كيلوغرام أو 3500 سعرة حرارية لكل رطل. التغير الحقيقي في وزن الجسم ديناميكي؛ هذه ليست توقعات فسيولوجية.","healthNote":"لا تخبرك هذه الصفحة بما يجب أن تأكله أو حجم العجز الذي يجب عليك اختياره. الصحة والأدوية والاحتياجات الفردية مهمة. اسأل أخصائي صحي مؤهل قبل تغيير النظام الغذائي أو النشاط. لا تستخدم هذا التقدير كنصيحة طبية.","sourceNiddk":"لماذا يكون تغير وزن الجسم ديناميكيًا:","sourceCdc":"معلومات التغيير التدريجي"},"actions":{"calculate":"حساب السيناريو","reset":"إعادة تعيين","example":"جرب المثال","copy":"نسخ النتيجة","result":"نتيجة السيناريو","kilograms":"كيلوغرام (كجم)","pounds":"جنيه (رطل)","dayUnit":"أيام","weekUnit":"أسابيع","kilocalories":"سعرة حرارية","perWeek":"في الأسبوع"},"messages":{"copied":"تم نسخ النتيجة.","copyUnavailable":"النسخة غير متوفرة في هذا المتصفح.","checkInputs":"أدخل وزنًا حاليًا موجبًا، وهدفًا لا يزيد عنه، وعجزًا يوميًا قدره صفر أو أكثر.","estimateOnly":"السيناريو الرياضي فقط - وليس التنبؤ بوزن الجسم أو توصية النظام الغذائي.","weightToLose":"فرق الوزن","energyEquivalent":"الطاقة الخطية المكافئة","timeline":"جدول زمني خطي بسيط","weeklyRate":"المعدل الأسبوعي الضمني","noDeficitChange":"مع وجود عجز مُدخل صفر، لا يُظهر هذا النموذج أي تغيير ولا يمكنه تقدير جدول زمني.","paceNote":"هذا السيناريو الخطي أعلى من وتيرة مراكز مكافحة الأمراض والوقاية منها (CDC) التي توصف غالبًا بأنها تدريجية بالنسبة للعديد من البالغين. إنه ليس هدفًا موصى به؛ اسأل أخصائي الصحة."},"additionalFaqs":[{"question":"هل هذا توقع لكمية الوزن التي سأخسرها؟","answer":"لا، فهو يطبق افتراضًا خطيًا ثابتًا لنسبة السعرات الحرارية إلى الوزن. يوضح نيدك أن تغير وزن الجسم هو تغير ديناميكي، لذا فإن هذه العملية الحسابية البسيطة يمكن أن تبالغ في تقدير التغير على المدى الطويل."},{"question":"ماذا يحدث عندما يكون العجز اليومي صفر؟","answer":"إن تغير الطاقة النموذجي هو صفر، لذلك لا تشير الصفحة إلى أي تغير في الوزن النموذجي ولا يوجد جدول زمني محدد."}]},"zh":{"copyLanguage":"zh","name":"减肥情景计算器","title":"免费减肥计算器 | UsefulVerse","description":"根据您自己的输入探索简单的体重目标时间表。 免费、私人的浏览器数学——不是饮食计划或体重预测。","intro":"探索一个透明、简化的能量平衡方案来实现体重目标。 这是算术，而不是对你的身体将如何反应的预测。","howQuestion":"这个减肥计算器是如何工作的？","howAnswer":"输入您想要检查的当前体重、较低目标体重和每日卡路里赤字。 该页面应用固定的线性每重量能量假设来显示数学场景。 它不建议卡路里赤字、制定饮食或预测您的实际体重变化。","privacyQuestion":"我的体重详细信息是否已上传？","privacyAnswer":"不会。计算在此浏览器中运行，输入的数字不会发送到服务器或由该页面保存。","fields":{"currentWeight":"当前重量","targetWeight":"目标重量","dailyDeficit":"这种情况下的每日热量不足（千卡）","unit":"重量单位","methodNote":"仅简化线性算术：每公斤 7,700 kcal 或每磅 3,500 kcal。真实体重变化是动态的； 这不是生理预测。","healthNote":"此页面不会告诉您吃什么或选择多大的赤字。 健康、药物和个人需求都很重要。 在改变饮食或活动之前咨询合格的健康专家； 请勿将此估计值用作医疗建议。","sourceNiddk":"为什么体重变化是动态的：","sourceCdc":"渐变信息"},"actions":{"calculate":"计算场景","reset":"重置","example":"尝试示例","copy":"复制结果","result":"场景结果","kilograms":"公斤(kg)","pounds":"磅 (lb)","dayUnit":"天","weekUnit":"周","kilocalories":"千卡","perWeek":"每周"},"messages":{"copied":"结果已复制。","copyUnavailable":"复制在此浏览器中不可用。","checkInputs":"输入正的当前体重、不高于该体重的目标以及零或更多的每日赤字。","estimateOnly":"仅是数学场景，不是体重预测或饮食建议。","weightToLose":"重量差异","energyEquivalent":"线性能量当量","timeline":"简单的线性时间线","weeklyRate":"隐含每周利率","noDeficitChange":"由于输入的赤字为零，该模型没有显示任何变化，并且无法估计时间表。","paceNote":"这种线性情景高于疾病预防控制中心的速度，通常被许多成年人描述为渐进的。 这不是一个推荐目标； 询问健康专业人士。"},"additionalFaqs":[{"question":"这是对我会减掉多少体重的预测吗？","answer":"不。它采用固定的卡路里与体重线性假设。 NIDDK 解释说，体重变化是动态的，因此这个简单的算术可能会夸大长期变化。"},{"question":"当每日赤字为零时会发生什么？","answer":"建模的能量变化为零，因此该页面报告没有建模的重量变化，也没有有限的时间线。"}]},"bn":{"copyLanguage":"bn","name":"ওজন হ্রাস দৃশ্যকল্প ক্যালকুলেটর","title":"ওজন কমানোর ক্যালকুলেটর বিনামূল্যে | UsefulVerse","description":"আপনার নিজের ইনপুট থেকে একটি সহজ ওজন-লক্ষ্য টাইমলাইন অন্বেষণ করুন। বিনামূল্যে, ব্যক্তিগত ব্রাউজার গণিত - একটি খাদ্য পরিকল্পনা বা শরীরের ওজন পূর্বাভাস নয়।","intro":"ওজন লক্ষ্যের জন্য একটি স্বচ্ছ, সরলীকৃত শক্তি-ভারসাম্যের দৃশ্যকল্প অন্বেষণ করুন। এটি পাটিগণিত, আপনার শরীর কীভাবে প্রতিক্রিয়া জানাবে তার পূর্বাভাস নয়।","howQuestion":"এই ওজন কমানোর ক্যালকুলেটর কিভাবে কাজ করে?","howAnswer":"একটি বর্তমান ওজন, একটি নিম্ন লক্ষ্য ওজন এবং একটি দৈনিক ক্যালোরি ঘাটতি লিখুন যা আপনি ইতিমধ্যে পরীক্ষা করতে চান। পৃষ্ঠাটি একটি গাণিতিক দৃশ্যকল্প দেখানোর জন্য একটি নির্দিষ্ট রৈখিক শক্তি-প্রতি-ওজন অনুমান প্রয়োগ করে। এটি একটি ক্যালোরি ঘাটতি সুপারিশ করে না, একটি খাদ্য তৈরি বা আপনার প্রকৃত ওজন পরিবর্তন পূর্বাভাস.","privacyQuestion":"আমার ওজন বিবরণ আপলোড করা হয়?","privacyAnswer":"না। গণনা এই ব্রাউজারে চলে এবং প্রবেশ করা নম্বরগুলি কোনো সার্ভারে পাঠানো হয় না বা এই পৃষ্ঠায় সংরক্ষিত হয় না।","fields":{"currentWeight":"বর্তমান ওজন","targetWeight":"লক্ষ্য ওজন","dailyDeficit":"এই দৃশ্যের জন্য দৈনিক ক্যালোরির ঘাটতি (kcal)","unit":"ওজন ইউনিট","methodNote":"শুধুমাত্র সরলীকৃত রৈখিক পাটিগণিত: প্রতি কেজি 7,700 kcal বা 3,500 kcal প্রতি পাউন্ড। প্রকৃত শরীরের ওজন পরিবর্তন গতিশীল; এটি একটি শারীরবৃত্তীয় পূর্বাভাস নয়।","healthNote":"এই পৃষ্ঠাটি আপনাকে কী খেতে হবে বা কত বড় ঘাটতি বেছে নিতে হবে তা বলে না। স্বাস্থ্য, ওষুধ এবং ব্যক্তিগত চাহিদা গুরুত্বপূর্ণ। ডায়েট বা কার্যকলাপ পরিবর্তন করার আগে একজন যোগ্য স্বাস্থ্য পেশাদারকে জিজ্ঞাসা করুন; চিকিৎসা পরামর্শ হিসাবে এই অনুমান ব্যবহার করবেন না.","sourceNiddk":"কেন শরীরের ওজন পরিবর্তন গতিশীল:","sourceCdc":"ধীরে ধীরে-পরিবর্তন তথ্য"},"actions":{"calculate":"পরিস্থিতি","reset":"গণনা করুন","example":"রিসেট করুন উদাহরণ","copy":"চেষ্টা করুন","result":"দৃশ্যের ফলাফল","kilograms":"কিলোগ্রাম (কেজি)","pounds":"পাউন্ড (lb)","dayUnit":"দিন","weekUnit":"সপ্তাহ","kilocalories":"kcal","perWeek":"প্রতি সপ্তাহে"},"messages":{"copied":"ফলাফল কপি করা হয়েছে।","copyUnavailable":"এই ব্রাউজারে অনুলিপি পাওয়া যায় না।","checkInputs":"একটি ইতিবাচক বর্তমান ওজন লিখুন, একটি লক্ষ্য এর চেয়ে বেশি নয় এবং দৈনিক ঘাটতি শূন্য বা তার বেশি।","estimateOnly":"শুধুমাত্র গাণিতিক দৃশ্যকল্প - শরীরের ওজনের পূর্বাভাস বা খাদ্যের সুপারিশ নয়।","weightToLose":"ওজনের পার্থক্য","energyEquivalent":"রৈখিক শক্তি সমতুল্য","timeline":"সাধারণ রৈখিক টাইমলাইন","weeklyRate":"উহ্য সাপ্তাহিক হার","noDeficitChange":"একটি শূন্য প্রবেশ করা ঘাটতি সহ, এই মডেল কোন পরিবর্তন দেখায় না এবং একটি সময়রেখা অনুমান করতে পারে না।","paceNote":"এই রৈখিক দৃশ্যকল্পটি অনেক প্রাপ্তবয়স্কদের জন্য ধীরে ধীরে বর্ণনা করা CDC গতির উপরে। এটি একটি প্রস্তাবিত লক্ষ্য নয়; একজন স্বাস্থ্য পেশাদারকে জিজ্ঞাসা করুন।"},"additionalFaqs":[{"question":"এই আমি কত ওজন হারাবো একটি ভবিষ্যদ্বাণী?","answer":"না। এটি একটি নির্দিষ্ট রৈখিক ক্যালোরি-থেকে-ওজন অনুমান প্রয়োগ করে। NIDDK ব্যাখ্যা করে যে শরীরের-ওজন পরিবর্তন গতিশীল, তাই এই সাধারণ পাটিগণিত দীর্ঘমেয়াদী পরিবর্তনকে অতিবৃদ্ধি করতে পারে।"},{"question":"দৈনিক ঘাটতি শূন্য হলে কী হবে?","answer":"মডেল করা শক্তি পরিবর্তন শূন্য, তাই পৃষ্ঠাটি কোন মডেল করা ওজন পরিবর্তন এবং কোন সীমাবদ্ধ টাইমলাইন রিপোর্ট করে না।"}]},"ru":{"copyLanguage":"ru","name":"Калькулятор сценариев похудения","title":"Калькулятор похудения бесплатно | UsefulVerse","description":"Изучите простую временную шкалу достижения целевого веса на основе ваших собственных данных. Бесплатная математика в частном браузере, а не план диеты или…","intro":"Изучите прозрачный и упрощенный сценарий энергетического баланса для достижения цели по весу. Это арифметика, а не прогноз того, как отреагирует ваше тело.","howQuestion":"Как работает этот калькулятор похудения?","howAnswer":"Введите текущий вес, более низкий целевой вес и ежедневный дефицит калорий, который вы уже хотите изучить. На странице применяется фиксированное линейное предположение об энергии на вес, чтобы показать математический сценарий. Он не рекомендует соблюдать дефицит калорий, составлять диету или прогнозировать фактическое изменение веса.","privacyQuestion":"Загружены ли данные о моем весе?","privacyAnswer":"Нет. Расчет выполняется в этом браузере, и введенные числа не отправляются на сервер и не сохраняются на этой странице.","fields":{"currentWeight":"Текущий вес","targetWeight":"Вес ворот","dailyDeficit":"Дневной дефицит калорий для этого сценария (ккал)","unit":"Весовая единица","methodNote":"Только упрощенная линейная арифметика: 7700 ккал на кг или 3500 ккал на фунт. Реальное изменение массы тела является динамическим; это не физиологический прогноз.","healthNote":"На этой странице не рассказывается, что есть или какой размер дефицита выбрать. Здоровье, лекарства и индивидуальные потребности имеют значение. Прежде чем менять диету или вид деятельности, проконсультируйтесь с квалифицированным медицинским работником; не используйте эту оценку в качестве медицинской рекомендации.","sourceNiddk":"Почему изменение массы тела является динамичным:","sourceCdc":"информация о постепенном изменении"},"actions":{"calculate":"Рассчитать сценарий","reset":"Сброс","example":"Попробуйте пример","copy":"Результат копирования","result":"Результат сценария","kilograms":"Килограммы (кг)","pounds":"Фунты (фунты)","dayUnit":"дней","weekUnit":"недели","kilocalories":"ккал","perWeek":"в неделю"},"messages":{"copied":"Результат скопирован.","copyUnavailable":"Копирование недоступно в этом браузере.","checkInputs":"Введите положительный текущий вес, цель не выше него и ежедневный дефицит, равный нулю или более.","estimateOnly":"Только математический сценарий, а не прогноз массы тела или рекомендации по диете.","weightToLose":"Разница в весе","energyEquivalent":"Эквивалент линейной энергии","timeline":"Простая линейная шкала времени","weeklyRate":"Подразумеваемая недельная ставка","noDeficitChange":"При нулевом введенном дефиците эта модель не показывает никаких изменений и не может оценить сроки.","paceNote":"Этот линейный сценарий превышает темпы CDC, которые для многих взрослых часто описываются как постепенные. Это не рекомендуемая цель; спросите медицинского работника."},"additionalFaqs":[{"question":"Это прогноз того, насколько сильно я похудею?","answer":"Нет. Здесь применяется фиксированное линейное соотношение калорий к весу. NIDDK объясняет, что изменение массы тела является динамическим, поэтому эта простая арифметика может преувеличить долгосрочные изменения."},{"question":"Что происходит, когда ежедневный дефицит равен нулю?","answer":"Смоделированное изменение энергии равно нулю, поэтому на странице не отображается ни смоделированное изменение веса, ни конечная временная шкала."}]},"ur":{"copyLanguage":"ur","name":"وزن میں کمی کے منظر نامے کیلکولیٹر","title":"وزن میں کمی کیلکولیٹر مفت | UsefulVerse","description":"اپنے ان پٹس سے وزن کے ہدف کی ایک سادہ ٹائم لائن دریافت کریں۔ مفت، پرائیویٹ براؤزر کی ریاضی — خوراک کا منصوبہ یا جسمانی وزن کی پیشن گوئی نہیں۔","intro":"وزن کے ہدف کے لیے ایک شفاف، آسان توانائی کے توازن کا منظرنامہ دریافت کریں۔ یہ ریاضی ہے، یہ پیشین گوئی نہیں کہ آپ کا جسم کیسے جواب دے گا۔","howQuestion":"یہ وزن کم کرنے والا کیلکولیٹر کیسے کام کرتا ہے؟","howAnswer":"موجودہ وزن، کم ہدف وزن اور روزانہ کیلوری کا خسارہ درج کریں جس کا آپ پہلے سے جائزہ لینا چاہتے ہیں۔ صفحہ ایک ریاضیاتی منظر نامے کو دکھانے کے لیے ایک مقررہ لکیری توانائی فی وزن کے مفروضے کا اطلاق کرتا ہے۔ یہ کیلوری کے خسارے کی سفارش نہیں کرتا، غذا تیار کرتا ہے یا آپ کے اصل وزن میں تبدیلی کی پیش گوئی نہیں کرتا ہے۔","privacyQuestion":"کیا میرے وزن کی تفصیلات اپ لوڈ کی گئی ہیں؟","privacyAnswer":"نہیں، حساب اس براؤزر میں چلتا ہے اور درج کردہ نمبرز سرور کو نہیں بھیجے جاتے اور نہ ہی اس صفحہ کے ذریعے محفوظ کیے جاتے ہیں۔","fields":{"currentWeight":"موجودہ وزن","targetWeight":"گول وزن","dailyDeficit":"اس منظر نامے کے لیے روزانہ کیلوری کا خسارہ (kcal)","unit":"وزن یونٹ","methodNote":"صرف آسان لکیری ریاضی: 7,700 kcal فی کلو یا 3,500 kcal فی lb۔ جسمانی وزن میں حقیقی تبدیلی متحرک ہے۔ یہ ایک جسمانی پیشن گوئی نہیں ہے.","healthNote":"یہ صفحہ آپ کو یہ نہیں بتاتا کہ کیا کھانا ہے یا کتنا بڑا خسارہ منتخب کرنا ہے۔ صحت، ادویات اور انفرادی ضروریات اہم ہیں۔ خوراک یا سرگرمی کو تبدیل کرنے سے پہلے ایک مستند صحت پیشہ ور سے پوچھیں؛ اس تخمینہ کو طبی مشورے کے طور پر استعمال نہ کریں۔","sourceNiddk":"جسمانی وزن میں تبدیلی کیوں متحرک ہے:","sourceCdc":"بتدریج تبدیلی کی معلومات"},"actions":{"calculate":"منظر نامے کا حساب لگائیں۔","reset":"دوبارہ ترتیب دیں۔","example":"مثال آزمائیں۔","copy":"نتیجہ کاپی کریں۔","result":"منظر نامے کا نتیجہ","kilograms":"کلوگرام (کلوگرام)","pounds":"پاؤنڈز (lb)","dayUnit":"دن","weekUnit":"ہفتے","kilocalories":"kcal","perWeek":"فی ہفتہ"},"messages":{"copied":"نتیجہ کاپی ہو گیا۔","copyUnavailable":"اس براؤزر میں کاپی دستیاب نہیں ہے۔","checkInputs":"ایک مثبت موجودہ وزن درج کریں، ایک ہدف اس سے زیادہ نہ ہو، اور صفر یا اس سے زیادہ کا روزانہ خسارہ درج کریں۔","estimateOnly":"صرف ریاضی کا منظر نامہ — جسمانی وزن کی پیشن گوئی یا خوراک کی سفارش نہیں۔","weightToLose":"وزن میں فرق","energyEquivalent":"لکیری توانائی کے مساوی","timeline":"سادہ لکیری ٹائم لائن","weeklyRate":"مضمر ہفتہ وار شرح","noDeficitChange":"صفر داخل شدہ خسارے کے ساتھ، یہ ماڈل کوئی تبدیلی نہیں دکھاتا اور ٹائم لائن کا اندازہ نہیں لگا سکتا۔","paceNote":"یہ لکیری منظرنامہ سی ڈی سی کی رفتار سے اوپر ہے جو اکثر بالغوں کے لیے بتدریج بیان کیا جاتا ہے۔ یہ ایک تجویز کردہ ہدف نہیں ہے۔ صحت کے پیشہ ور سے پوچھیں."},"additionalFaqs":[{"question":"کیا یہ پیشین گوئی ہے کہ میں کتنا وزن کم کروں گا؟","answer":"نہیں، یہ ایک مقررہ لکیری کیلوری سے وزن کے مفروضے کا اطلاق کرتا ہے۔ NIDDK وضاحت کرتا ہے کہ جسمانی وزن میں تبدیلی متحرک ہے، لہذا یہ سادہ ریاضی طویل مدتی تبدیلی کو بڑھاوا دے سکتا ہے۔"},{"question":"جب روزانہ خسارہ صفر ہو تو کیا ہوتا ہے؟","answer":"ماڈل شدہ توانائی کی تبدیلی صفر ہے، لہذا صفحہ کسی ماڈل شدہ وزن میں تبدیلی اور کوئی محدود ٹائم لائن کی اطلاع نہیں دیتا ہے۔"}]},"tr":{"copyLanguage":"tr","name":"Kilo verme senaryosu hesaplayıcı","title":"Kilo kaybı hesaplayıcısı ücretsiz | UsefulVerse","description":"Kendi girdilerinizden yola çıkarak basit bir ağırlık hedefi zaman çizelgesini keşfedin. Ücretsiz, özel tarayıcı matematiği; bir diyet planı veya vücut…","intro":"Ağırlık hedefi için şeffaf, basitleştirilmiş bir enerji dengesi senaryosunu keşfedin. Bu aritmetiktir, vücudunuzun nasıl tepki vereceğine dair bir tahmin değildir.","howQuestion":"Bu kilo verme hesaplayıcısı nasıl çalışır?","howAnswer":"Mevcut kilonuzu, daha düşük hedef kilonuzu ve zaten incelemek istediğiniz günlük kalori açığınızı girin. Sayfa, matematiksel bir senaryoyu göstermek için ağırlık başına sabit bir doğrusal enerji varsayımı uygular. Kalori açığı önermez, diyet oluşturmaz veya gerçek kilo değişiminizi tahmin etmez.","privacyQuestion":"Kilo bilgilerim yüklendi mi?","privacyAnswer":"Hayır. Hesaplama bu tarayıcıda yapılır ve girilen sayılar bir sunucuya gönderilmez veya bu sayfa tarafından kaydedilmez.","fields":{"currentWeight":"Mevcut ağırlık","targetWeight":"Hedef ağırlığı","dailyDeficit":"Bu senaryo için günlük kalori açığı (kcal)","unit":"Ağırlık birimi","methodNote":"Yalnızca basitleştirilmiş doğrusal aritmetik: kg başına 7.700 kcal veya lb başına 3.500 kcal. Gerçek vücut ağırlığı değişimi dinamiktir; bu fizyolojik bir tahmin değil.","healthNote":"Bu sayfa size ne yemeniz gerektiğini veya ne kadar büyük bir açığı seçeceğinizi söylemez. Sağlık, ilaçlar ve bireysel ihtiyaçlar önemlidir. Diyetinizi veya aktivitenizi değiştirmeden önce kalifiye bir sağlık uzmanına danışın; Bu tahmini tıbbi tavsiye olarak kullanmayın.","sourceNiddk":"Vücut ağırlığı değişimi neden dinamiktir:","sourceCdc":"kademeli değişim bilgileri"},"actions":{"calculate":"Senaryoyu hesapla","reset":"Sıfırla","example":"Örneği deneyin","copy":"Sonucu kopyala","result":"Senaryo sonucu","kilograms":"Kilogram (kg)","pounds":"Pound (lb)","dayUnit":"gün","weekUnit":"hafta","kilocalories":"kcal","perWeek":"haftada"},"messages":{"copied":"Sonuç kopyalandı.","copyUnavailable":"Kopyalama bu tarayıcıda mevcut değil.","checkInputs":"Pozitif bir mevcut ağırlık, bundan daha yüksek olmayan bir hedef ve sıfır veya daha fazla günlük açık girin.","estimateOnly":"Yalnızca matematiksel senaryo; vücut ağırlığı tahmini veya diyet önerisi değil.","weightToLose":"Ağırlık farkı","energyEquivalent":"Doğrusal enerji eşdeğeri","timeline":"Basit doğrusal zaman çizelgesi","weeklyRate":"İma edilen haftalık oran","noDeficitChange":"Sıfır girilen açıkla bu model hiçbir değişiklik göstermez ve bir zaman çizelgesi tahmin edemez.","paceNote":"Bu doğrusal senaryo, çoğu yetişkin için sıklıkla kademeli olarak tanımlanan CDC hızının üzerindedir. Önerilen bir hedef değildir; bir sağlık uzmanına sorun."},"additionalFaqs":[{"question":"Bu ne kadar kilo vereceğime dair bir tahmin mi?","answer":"Hayır. Sabit bir doğrusal kalori-ağırlık varsayımı uygular. NIDDK, vücut ağırlığındaki değişimin dinamik olduğunu, dolayısıyla bu basit aritmetiğin uzun vadeli değişimi abartabileceğini açıklıyor."},{"question":"Günlük açık sıfır olduğunda ne olur?","answer":"Modellenen enerji değişimi sıfır olduğundan sayfa, modellenmiş bir ağırlık değişimi ve sonlu bir zaman çizelgesi bildirmemektedir."}]},"vi":{"copyLanguage":"vi","name":"Máy tính kịch bản giảm cân","title":"Máy tính giảm cân miễn phí | UsefulVerse","description":"Khám phá dòng thời gian mục tiêu cân nặng đơn giản từ thông tin đầu vào của riêng bạn. Toán học trình duyệt riêng tư, miễn phí—không phải là kế hoạch ăn…","intro":"Khám phá kịch bản cân bằng năng lượng đơn giản, minh bạch cho mục tiêu cân nặng. Đó là số học, không phải là dự đoán về cách cơ thể bạn sẽ phản ứng.","howQuestion":"Máy tính giảm cân này hoạt động như thế nào?","howAnswer":"Nhập cân nặng hiện tại, cân nặng mục tiêu thấp hơn và mức thâm hụt calo hàng ngày mà bạn muốn kiểm tra. Trang này áp dụng giả định năng lượng trên mỗi trọng lượng tuyến tính cố định để hiển thị một kịch bản toán học. Nó không khuyến nghị giảm lượng calo, tạo chế độ ăn kiêng hoặc dự đoán sự thay đổi cân nặng thực tế của bạn.","privacyQuestion":"Chi tiết cân nặng của tôi có được tải lên không?","privacyAnswer":"Không. Phép tính chạy trong trình duyệt này và các số đã nhập không được gửi đến máy chủ hoặc được trang này lưu.","fields":{"currentWeight":"Trọng lượng hiện tại","targetWeight":"Trọng lượng mục tiêu","dailyDeficit":"Lượng calo thiếu hụt hàng ngày cho tình huống này (kcal)","unit":"Đơn vị trọng lượng","methodNote":"Chỉ số học tuyến tính đơn giản hóa: 7.700 kcal mỗi kg hoặc 3.500 kcal mỗi lb. Sự thay đổi trọng lượng cơ thể thực là linh hoạt; đây không phải là một dự báo sinh lý.","healthNote":"Trang này không cho bạn biết nên ăn gì hoặc chọn mức thâm hụt lớn như thế nào. Sức khỏe, thuốc men và nhu cầu cá nhân đều quan trọng. Hãy hỏi chuyên gia y tế có trình độ trước khi thay đổi chế độ ăn uống hoặc hoạt động; không sử dụng ước tính này như lời khuyên y tế.","sourceNiddk":"Tại sao trọng lượng cơ thể thay đổi mạnh mẽ:","sourceCdc":"thông tin thay đổi dần dần"},"actions":{"calculate":"Tính toán kịch bản","reset":"Đặt lại","example":"Hãy thử ví dụ","copy":"Sao chép kết quả","result":"Kết quả kịch bản","kilograms":"Kilôgam (kg)","pounds":"Cân Anh (lb)","dayUnit":"ngày","weekUnit":"tuần","kilocalories":"kcal","perWeek":"mỗi tuần"},"messages":{"copied":"Đã sao chép kết quả.","copyUnavailable":"Bản sao không có sẵn trong trình duyệt này.","checkInputs":"Nhập trọng lượng hiện tại dương, mục tiêu không cao hơn mục tiêu đó và mức thâm hụt hàng ngày từ 0 trở lên.","estimateOnly":"Chỉ là kịch bản toán học—không phải dự đoán trọng lượng cơ thể hay khuyến nghị về chế độ ăn uống.","weightToLose":"Chênh lệch trọng lượng","energyEquivalent":"Năng lượng tuyến tính tương đương","timeline":"Dòng thời gian tuyến tính đơn giản","weeklyRate":"Tỷ giá ngầm định hàng tuần","noDeficitChange":"Với mức thâm hụt được nhập bằng 0, mô hình này không hiển thị thay đổi và không thể ước tính mốc thời gian.","paceNote":"Kịch bản tuyến tính này cao hơn tốc độ của CDC thường được mô tả là diễn ra từ từ đối với nhiều người lớn. Đó không phải là mục tiêu được đề xuất; hãy hỏi chuyên gia y tế."},"additionalFaqs":[{"question":"Đây có phải là dự đoán về việc tôi sẽ giảm bao nhiêu cân?","answer":"Không. Nó áp dụng giả định tuyến tính về lượng calo trên trọng lượng. NIDDK giải thích rằng sự thay đổi trọng lượng cơ thể là động, vì vậy số học đơn giản này có thể phóng đại sự thay đổi dài hạn."},{"question":"Điều gì xảy ra khi mức thâm hụt hàng ngày bằng 0?","answer":"Sự thay đổi năng lượng được mô hình hóa bằng 0, vì vậy trang này báo cáo không có sự thay đổi trọng lượng được mô hình hóa và không có dòng thời gian hữu hạn."}]},"it":{"copyLanguage":"it","name":"Calcolatore dello scenario di perdita di peso","title":"Calcolatore di perdita di peso gratuito | UsefulVerse","description":"Esplora una semplice sequenza temporale dell'obiettivo di peso in base ai tuoi input. Matematica gratuita e privata del browser: non un programma dietetico…","intro":"Esplora uno scenario di bilancio energetico trasparente e semplificato per un obiettivo di peso. È aritmetica, non una previsione di come risponderà il tuo corpo.","howQuestion":"Come funziona questo calcolatore di perdita di peso?","howAnswer":"Inserisci un peso attuale, un obiettivo di peso inferiore e un deficit calorico giornaliero che desideri già esaminare. La pagina applica un'ipotesi lineare fissa di energia per peso per mostrare uno scenario matematico. Non consiglia un deficit calorico, crea una dieta o prevede l'effettivo cambiamento di peso.","privacyQuestion":"I dettagli del mio peso sono stati caricati?","privacyAnswer":"No. Il calcolo viene eseguito in questo browser e i numeri inseriti non vengono inviati a un server o salvati da questa pagina.","fields":{"currentWeight":"Peso attuale","targetWeight":"Peso obiettivo","dailyDeficit":"Deficit calorico giornaliero per questo scenario (kcal)","unit":"Unità di peso","methodNote":"Solo aritmetica lineare semplificata: 7.700 kcal per kg o 3.500 kcal per lb. La variazione reale del peso corporeo è dinamica; questa non è una previsione fisiologica.","healthNote":"Questa pagina non ti dice cosa mangiare o quanto grande è il deficit da scegliere. La salute, i medicinali e i bisogni individuali contano. Chiedi a un operatore sanitario qualificato prima di cambiare dieta o attività; non utilizzare questa stima come consiglio medico.","sourceNiddk":"Perché il cambiamento del peso corporeo è dinamico:","sourceCdc":"informazioni sulla modifica graduale"},"actions":{"calculate":"Calcola lo scenario","reset":"Reimposta","example":"Prova l'esempio","copy":"Copia il risultato","result":"Risultato dello scenario","kilograms":"Chilogrammi (kg)","pounds":"Libbre (libbre)","dayUnit":"giorni","weekUnit":"settimane","kilocalories":"kcal","perWeek":"a settimana"},"messages":{"copied":"Risultato copiato.","copyUnavailable":"La copia non è disponibile in questo browser.","checkInputs":"Inserisci un peso attuale positivo, un obiettivo non superiore a questo e un deficit giornaliero pari o superiore a zero.","estimateOnly":"Solo scenario matematico, non una previsione del peso corporeo o una raccomandazione dietetica.","weightToLose":"Differenza di peso","energyEquivalent":"Energia lineare equivalente","timeline":"Cronologia lineare semplice","weeklyRate":"Tariffa settimanale implicita","noDeficitChange":"Con un deficit inserito pari a zero, questo modello non mostra alcun cambiamento e non può stimare una sequenza temporale.","paceNote":"Questo scenario lineare è superiore al ritmo CDC spesso descritto come graduale per molti adulti. Non è un obiettivo consigliato; chiedi a un operatore sanitario."},"additionalFaqs":[{"question":"È una previsione di quanto peso perderò?","answer":"No. Si applica un presupposto lineare fisso calorie/peso. Il NIDDK spiega che il cambiamento del peso corporeo è dinamico, quindi questa semplice aritmetica può sopravvalutare il cambiamento a lungo termine."},{"question":"Cosa succede quando il deficit giornaliero è pari a zero?","answer":"La variazione di energia modellata è pari a zero, quindi la pagina non riporta alcuna variazione di peso modellata e nessuna sequenza temporale finita."}]},"zh_tw":{"copyLanguage":"zh_tw","name":"減肥情境計算器","title":"免費減肥計算器 | UsefulVerse","description":"根據您自己的輸入探索簡單的體重目標時間表。免費、私人的瀏覽器數學——不是飲食計劃或體重預測。","intro":"探索一個透明、簡化的能量平衡方案來實現體重目標。這是算術，而不是對你的身體將如何反應的預測。","howQuestion":"這個減肥計算器是如何運作的？","howAnswer":"輸入您想要檢查的當前體重、較低目標體重和每日卡路里赤字。該頁面應用固定的線性每重量能量假設來顯示數學場景。它不建議卡路里赤字、制定飲食或預測您的實際體重變化。","privacyQuestion":"我的體重詳細資料是否已上傳？","privacyAnswer":"不會。計算在此瀏覽器中運行，輸入的數字不會發送到伺服器或由該頁面保存。","fields":{"currentWeight":"當前重量","targetWeight":"目標重量","dailyDeficit":"這種情況下的每日熱量不足（千卡）","unit":"重量單位","methodNote":"僅簡化線性算術：每公斤 7,700 kcal 或每磅 3,500 kcal。真實體重變化是動態的；這不是生理預測。","healthNote":"此頁面不會告訴您吃什麼或選擇多大的赤字。健康、藥物和個人需求都很重要。在改變飲食或活動之前諮詢合格的健康專家；請勿將此估計值用作醫療建議。","sourceNiddk":"為什麼體重變化是動態的：","sourceCdc":"漸變資訊"},"actions":{"calculate":"計算場景","reset":"重置","example":"試試範例","copy":"複製結果","result":"場景結果","kilograms":"公斤(kg)","pounds":"磅 (lb)","dayUnit":"天","weekUnit":"週","kilocalories":"千卡","perWeek":"每週"},"messages":{"copied":"結果已複製。","copyUnavailable":"複製在此瀏覽器中不可用。","checkInputs":"輸入正的當前體重、不高於該體重的目標以及零或更多的每日赤字。","estimateOnly":"仅是数学场景，不是体重预测或饮食建议。","weightToLose":"重量差异","energyEquivalent":"線性能量當量","timeline":"簡單的線性時間軸","weeklyRate":"隱含每週利率","noDeficitChange":"由於輸入的赤字為零，因此模型沒有顯示任何變化，並且無法估計時間表。","paceNote":"這種線性情境高於疾病預防控制中心的速度，通常被許多成年人描述為漸進的。這不是一個推薦目標；詢問健康專業人士。"},"additionalFaqs":[{"question":"這是我會減掉多少體重的預測嗎？","answer":"不。它採用固定的卡路里與體重線性假設。 NIDDK 解釋說，體重變化是動態的，因此這個簡單的算術可能會誇大長期變化。"},{"question":"當每日赤字為零時會發生什麼事？","answer":"建模的能量變化為零，因此該頁面報告沒有建模的重量變化，也沒有有限的時間線。"}]},"bg":{"copyLanguage":"bg","name":"Калкулатор за сценарий за загуба на тегло","title":"Безплатен калкулатор за отслабване | UsefulVerse","description":"Разгледайте проста времева линия за тегло и цел от собствените си данни. Безплатна, частна математика на браузъра - не диетичен план или прогноза за…","intro":"Разгледайте прозрачен, опростен сценарий за енергиен баланс за целево тегло. Това е аритметика, а не прогноза за това как тялото ви ще реагира.","howQuestion":"Как работи този калкулатор за отслабване?","howAnswer":"Въведете текущо тегло, по-ниско целево тегло и дневен калориен дефицит, който вече искате да проверите. Страницата прилага предположение за фиксирана линейна енергия на тегло, за да покаже математически сценарий. Той не препоръчва калориен дефицит, не създава диета или предвижда действителната промяна на теглото ви.","privacyQuestion":"Качени ли са данните за теглото ми?","privacyAnswer":"Не. Изчислението се изпълнява в този браузър и въведените числа не се изпращат на сървър или се запазват от тази страница.","fields":{"currentWeight":"Текущо тегло","targetWeight":"Целево тегло","dailyDeficit":"Дневен калориен дефицит за този сценарий (kcal)","unit":"Единица за тегло","methodNote":"Само опростена линейна аритметика: 7700 kcal на kg или 3500 kcal на lb. Реалната промяна на телесното тегло е динамична; това не е физиологична прогноза.","healthNote":"Тази страница не ви казва какво да ядете или колко голям дефицит да изберете. Здравето, лекарствата и индивидуалните нужди имат значение. Посъветвайте се с квалифициран здравен специалист, преди да промените диетата или дейността си; не използвайте тази оценка като медицински съвет.","sourceNiddk":"Защо промяната на телесното тегло е динамична:","sourceCdc":"информация за постепенна промяна"},"actions":{"calculate":"Изчислете сценария","reset":"Нулирайте","example":"Опитайте пример","copy":"Копирайте резултата","result":"Резултат от сценария","kilograms":"Килограми (kg)","pounds":"Паундове (lb)","dayUnit":"дни","weekUnit":"седмици","kilocalories":"kcal","perWeek":"на седмица"},"messages":{"copied":"Резултатът е копиран.","copyUnavailable":"Копирането не е налично в този браузър.","checkInputs":"Въведете положително текущо тегло, цел не по-висока от него и дневен дефицит от нула или повече.","estimateOnly":"Само математически сценарий - не предвиждане на телесното тегло или препоръка за диета.","weightToLose":"Разлика в теглото","energyEquivalent":"Линеен енергиен еквивалент","timeline":"Проста линейна времева линия","weeklyRate":"Подразбираща се седмична ставка","noDeficitChange":"При нулев въведен дефицит, този модел не показва промяна и не може да оцени времевата линия.","paceNote":"Този линеен сценарий е над темпото на CDC, често описван като постепенно за много възрастни. Не е препоръчителна цел; попитайте здравен специалист."},"additionalFaqs":[{"question":"Това прогноза ли е за това колко тегло ще отслабна?","answer":"Не. Прилага фиксирано линейно предположение за съотношение калории към тегло. NIDDK обяснява, че промяната на телесното тегло е динамична, така че тази проста аритметика може да надценява дългосрочната промяна."},{"question":"Какво се случва, когато дневният дефицит е нула?","answer":"Моделираната промяна на енергията е нула, така че страницата не отчита моделирана промяна на теглото и няма ограничена времева линия."}]},"ca":{"copyLanguage":"ca","name":"Calculadora d'escenaris de pèrdua de pes","title":"Calculadora de pèrdua de pes gratis | UsefulVerse","description":"Exploreu una línia de temps senzilla d'objectius de pes a partir de les vostres pròpies aportacions. Matemàtiques gratuïtes i privades del navegador, no un…","intro":"Exploreu un escenari de balanç energètic transparent i simplificat per a un objectiu de pes. És aritmètica, no una predicció de com respondrà el teu cos.","howQuestion":"Com funciona aquesta calculadora de pèrdua de pes?","howAnswer":"Introduïu un pes actual, un pes objectiu inferior i un dèficit calòric diari que ja voleu examinar. La pàgina aplica una hipòtesi d'energia per pes lineal fixa per mostrar un escenari matemàtic. No recomana un dèficit calòric, crear una dieta o predir el vostre canvi de pes real.","privacyQuestion":"S'han penjat els meus detalls de pes?","privacyAnswer":"No. El càlcul s'executa en aquest navegador i els números introduïts no s'envien a un servidor ni s'emmagatzemen en aquesta pàgina.","fields":{"currentWeight":"Pes actual","targetWeight":"Pes de l'objectiu","dailyDeficit":"Dèficit calòric diari per a aquest escenari (kcal)","unit":"Unitat de pes","methodNote":"Només aritmètica lineal simplificada: 7.700 kcal per kg o 3.500 kcal per lb. El canvi real del pes corporal és dinàmic; aquesta no és una previsió fisiològica.","healthNote":"Aquesta pàgina no us indica què menjar o quin dèficit ha de triar. La salut, els medicaments i les necessitats individuals són importants. Pregunteu a un professional sanitari qualificat abans de canviar la dieta o l'activitat; no utilitzeu aquesta estimació com a consell mèdic.","sourceNiddk":"Per què el canvi de pes corporal és dinàmic:","sourceCdc":"informació de canvi gradual"},"actions":{"calculate":"Calcula l'escenari","reset":"Restableix","example":"Proveu l'exemple","copy":"Copia el resultat","result":"Resultat de l'escenari","kilograms":"Quilograms (kg)","pounds":"Lliures (lb)","dayUnit":"dies","weekUnit":"setmanes","kilocalories":"kcal","perWeek":"per setmana"},"messages":{"copied":"S'ha copiat el resultat.","copyUnavailable":"La còpia no està disponible en aquest navegador.","checkInputs":"Introduïu un pes actual positiu, un objectiu no superior a aquest i un dèficit diari de zero o més.","estimateOnly":"Escenari matemàtic només, no una predicció del pes corporal ni una recomanació de dieta.","weightToLose":"Diferència de pes","energyEquivalent":"Equivalent d'energia lineal","timeline":"Línia de temps lineal simple","weeklyRate":"Tarifa setmanal implícita","noDeficitChange":"Amb un dèficit introduït zero, aquest model no mostra cap canvi i no pot estimar una línia de temps.","paceNote":"Aquest escenari lineal està per sobre del ritme dels CDC que sovint es descriu com a gradual per a molts adults. No és un objectiu recomanat; preguntar a un professional de la salut."},"additionalFaqs":[{"question":"És aquesta una predicció de quant de pes perdré?","answer":"No. Aplica una hipòtesi lineal fixa de calories a pes. NIDDK explica que el canvi de pes corporal és dinàmic, de manera que aquesta simple aritmètica pot exagerar el canvi a llarg termini."},{"question":"Què passa quan el dèficit diari és zero?","answer":"El canvi d'energia modelat és zero, de manera que la pàgina no informa cap canvi de pes modelat i cap línia de temps finita."}]},"nl":{"copyLanguage":"nl","name":"Scenariocalculator voor gewichtsverlies","title":"Gratis calculator voor gewichtsverlies | UsefulVerse","description":"Verken een eenvoudige tijdlijn met gewichtsdoelen op basis van uw eigen gegevens. Gratis privé-browserwiskunde, geen dieetplan of voorspelling van het…","intro":"Ontdek een transparant, vereenvoudigd energiebalansscenario voor een gewichtsdoel. Het is rekenkundig, geen voorspelling van hoe uw lichaam zal reageren.","howQuestion":"Hoe werkt deze gewichtsverliescalculator?","howAnswer":"Voer een huidig ​​gewicht in, een lager streefgewicht en een dagelijks calorietekort dat je al wilt onderzoeken. De pagina past een vaste lineaire aanname van energie per gewicht toe om een ​​wiskundig scenario weer te geven. Het raadt geen calorietekort aan, stelt geen dieet samen en voorspelt niet uw werkelijke gewichtsverandering.","privacyQuestion":"Worden mijn gewichtsgegevens geüpload?","privacyAnswer":"Nee. De berekening wordt in deze browser uitgevoerd en de ingevoerde getallen worden niet naar een server verzonden of door deze pagina opgeslagen.","fields":{"currentWeight":"Huidig gewicht","targetWeight":"Doelgewicht","dailyDeficit":"Dagelijks calorietekort voor dit scenario (kcal)","unit":"Gewichtseenheid","methodNote":"Alleen vereenvoudigde lineaire rekenkunde: 7.700 kcal per kg of 3.500 kcal per lb. De werkelijke verandering in lichaamsgewicht is dynamisch; dit is geen fysiologische voorspelling.","healthNote":"Op deze pagina staat niet wat je moet eten of hoe groot een tekort je moet kiezen. Gezondheid, medicijnen en individuele behoeften zijn van belang. Vraag een gekwalificeerde zorgverlener voordat u van dieet of activiteit verandert; gebruik deze schatting niet als medisch advies.","sourceNiddk":"Waarom verandering in lichaamsgewicht dynamisch is:","sourceCdc":"geleidelijke veranderingsinformatie"},"actions":{"calculate":"Scenario berekenen","reset":"Opnieuw instellen","example":"Probeer voorbeeld","copy":"Kopieer resultaat","result":"Scenarioresultaat","kilograms":"Kilogrammen (kg)","pounds":"Ponden (lb)","dayUnit":"dagen","weekUnit":"weken","kilocalories":"kcal","perWeek":"per week"},"messages":{"copied":"Resultaat gekopieerd.","copyUnavailable":"Kopiëren is niet beschikbaar in deze browser.","checkInputs":"Voer een positief huidig gewicht in, een doel dat niet hoger is dan dit gewicht, en een dagelijks tekort van nul of meer.","estimateOnly":"Alleen een wiskundig scenario – geen voorspelling van het lichaamsgewicht of een dieetaanbeveling.","weightToLose":"Gewichtsverschil","energyEquivalent":"Lineair energie-equivalent","timeline":"Eenvoudige lineaire tijdlijn","weeklyRate":"Impliciet weektarief","noDeficitChange":"Met een nul ingevoerd tekort vertoont dit model geen verandering en kan het geen tijdlijn schatten.","paceNote":"Dit lineaire scenario ligt boven het CDC-tempo dat voor veel volwassenen vaak als geleidelijk wordt omschreven. Het is geen aanbevolen doel; vraag het aan een gezondheidsprofessional."},"additionalFaqs":[{"question":"Is dit een voorspelling van hoeveel gewicht ik zal verliezen?","answer":"Nee. Er wordt een vaste lineaire aanname van calorieën naar gewicht toegepast. NIDDK legt uit dat veranderingen in lichaamsgewicht dynamisch zijn, dus deze eenvoudige rekensom kan de veranderingen op de langere termijn overdrijven."},{"question":"Wat gebeurt er als het dagelijkse tekort nul is?","answer":"De gemodelleerde energieverandering is nul, dus de pagina rapporteert geen gemodelleerde gewichtsverandering en geen eindige tijdlijn."}]},"el":{"copyLanguage":"el","name":"Αριθμομηχανή σεναρίου απώλειας βάρους","title":"Αριθμομηχανή απώλειας βάρους δωρεάν | UsefulVerse","description":"Εξερευνήστε ένα απλό χρονοδιάγραμμα βάρους-στόχων από τα δικά σας στοιχεία. Δωρεάν, ιδιωτικό πρόγραμμα περιήγησης μαθηματικά—όχι πρόγραμμα διατροφής ή…","intro":"Εξερευνήστε ένα διαφανές, απλοποιημένο σενάριο εξισορρόπησης ενέργειας για έναν στόχο βάρους. Είναι αριθμητική, όχι μια πρόβλεψη για το πώς θα ανταποκριθεί το σώμα σας.","howQuestion":"Πώς λειτουργεί αυτή η αριθμομηχανή απώλειας βάρους;","howAnswer":"Εισαγάγετε ένα τρέχον βάρος, ένα χαμηλότερο βάρος στόχου και ένα ημερήσιο έλλειμμα θερμίδων που θέλετε ήδη να εξετάσετε. Η σελίδα εφαρμόζει μια σταθερή γραμμική υπόθεση ενέργειας ανά βάρος για να εμφανίσει ένα μαθηματικό σενάριο. Δεν συνιστά έλλειμμα θερμίδων, δεν δημιουργεί δίαιτα ή δεν προβλέπει την πραγματική αλλαγή βάρους σας.","privacyQuestion":"Ανεβαίνουν τα στοιχεία του βάρους μου;","privacyAnswer":"Όχι. Ο υπολογισμός εκτελείται σε αυτό το πρόγραμμα περιήγησης και οι αριθμοί που εισάγονται δεν αποστέλλονται σε διακομιστή ούτε αποθηκεύονται από αυτήν τη σελίδα.","fields":{"currentWeight":"Τρέχον βάρος","targetWeight":"Βάρος στόχου","dailyDeficit":"Ημερήσιο έλλειμμα θερμίδων για αυτό το σενάριο (kcal)","unit":"Μονάδα βάρους","methodNote":"Μόνο απλοποιημένη γραμμική αριθμητική: 7.700 kcal ανά kg ή 3.500 kcal ανά λίβρα. Η πραγματική αλλαγή σωματικού βάρους είναι δυναμική. αυτό δεν είναι μια φυσιολογική πρόβλεψη.","healthNote":"Αυτή η σελίδα δεν σας λέει τι να φάτε ή πόσο μεγάλο έλλειμμα να επιλέξετε. Η υγεία, τα φάρμακα και οι ατομικές ανάγκες έχουν σημασία. Ρωτήστε έναν εξειδικευμένο επαγγελματία υγείας πριν αλλάξετε διατροφή ή δραστηριότητα. μην χρησιμοποιείτε αυτήν την εκτίμηση ως ιατρική συμβουλή.","sourceNiddk":"Γιατί η αλλαγή σωματικού βάρους είναι δυναμική:","sourceCdc":"σταδιακή αλλαγή πληροφοριών"},"actions":{"calculate":"Υπολογίστε το σενάριο","reset":"Επαναφορά","example":"Δοκιμάστε το παράδειγμα","copy":"Αντιγράψτε το αποτέλεσμα","result":"Αποτέλεσμα σεναρίου","kilograms":"Κιλά (kg)","pounds":"Λίρες (lb)","dayUnit":"ημέρες","weekUnit":"εβδομάδες","kilocalories":"kcal","perWeek":"την εβδομάδα"},"messages":{"copied":"Το αποτέλεσμα αντιγράφηκε.","copyUnavailable":"Το αντίγραφο δεν είναι διαθέσιμο σε αυτό το πρόγραμμα περιήγησης.","checkInputs":"Εισαγάγετε ένα θετικό τρέχον βάρος, έναν στόχο όχι μεγαλύτερο από αυτό και ένα ημερήσιο έλλειμμα μηδέν ή περισσότερο.","estimateOnly":"Μόνο μαθηματικό σενάριο—όχι πρόβλεψη σωματικού βάρους ή σύσταση δίαιτας.","weightToLose":"Διαφορά βάρους","energyEquivalent":"Ισοδύναμο γραμμικής ενέργειας","timeline":"Απλή γραμμική γραμμή χρόνου","weeklyRate":"Τεκμαρτή εβδομαδιαία τιμή","noDeficitChange":"Με μηδενικό εισαγόμενο έλλειμμα, αυτό το μοντέλο δεν παρουσιάζει καμία αλλαγή και δεν μπορεί να εκτιμήσει ένα χρονοδιάγραμμα.","paceNote":"Αυτό το γραμμικό σενάριο είναι πάνω από το ρυθμό CDC που συχνά περιγράφεται ως σταδιακό για πολλούς ενήλικες. Δεν είναι ένας προτεινόμενος στόχος. ρωτήστε έναν επαγγελματία υγείας."},"additionalFaqs":[{"question":"Είναι αυτή μια πρόβλεψη για το πόσο βάρος θα χάσω;","answer":"Όχι. Εφαρμόζει μια σταθερή γραμμική υπόθεση θερμίδων προς βάρος. Η NIDDK εξηγεί ότι η αλλαγή σωματικού βάρους είναι δυναμική, επομένως αυτή η απλή αριθμητική μπορεί να υπερεκτιμήσει τη μακροπρόθεσμη αλλαγή."},{"question":"Τι συμβαίνει όταν το ημερήσιο έλλειμμα είναι μηδέν;","answer":"Η μοντελοποιημένη αλλαγή ενέργειας είναι μηδενική, επομένως η σελίδα δεν αναφέρει καμία αλλαγή βάρους βάσει μοντέλου και κανένα πεπερασμένο χρονοδιάγραμμα."}]},"ms":{"copyLanguage":"ms","name":"Kalkulator senario penurunan berat badan","title":"Kalkulator penurunan berat badan percuma | UsefulVerse","description":"Teroka garis masa matlamat berat mudah daripada input anda sendiri. Matematik pelayar peribadi percuma—bukan pelan diet atau ramalan berat badan.","intro":"Terokai senario keseimbangan tenaga yang telus dan dipermudahkan untuk matlamat berat. Ia adalah aritmetik, bukan ramalan bagaimana badan anda akan bertindak balas.","howQuestion":"Bagaimanakah kalkulator penurunan berat badan ini berfungsi?","howAnswer":"Masukkan berat semasa, berat matlamat yang lebih rendah dan defisit kalori harian yang anda sudah mahu periksa. Halaman ini menggunakan andaian tenaga setiap berat linear tetap untuk menunjukkan senario matematik. Ia tidak mengesyorkan defisit kalori, membuat diet atau meramalkan perubahan berat badan sebenar anda.","privacyQuestion":"Adakah butiran berat saya dimuat naik?","privacyAnswer":"Tidak. Pengiraan berjalan dalam pelayar ini dan nombor yang dimasukkan tidak dihantar ke pelayan atau disimpan oleh halaman ini.","fields":{"currentWeight":"Berat semasa","targetWeight":"Berat matlamat","dailyDeficit":"Defisit kalori harian untuk senario ini (kcal)","unit":"Unit berat","methodNote":"Aritmetik linear ringkas sahaja: 7,700 kcal per kg atau 3,500 kcal per lb. Perubahan berat badan sebenar adalah dinamik; ini bukan ramalan fisiologi.","healthNote":"Halaman ini tidak memberitahu anda apa yang perlu dimakan atau berapa besar defisit untuk dipilih. Kesihatan, ubat-ubatan dan keperluan individu penting. Tanya profesional kesihatan yang berkelayakan sebelum menukar diet atau aktiviti; jangan gunakan anggaran ini sebagai nasihat perubatan.","sourceNiddk":"Mengapa perubahan berat badan adalah dinamik:","sourceCdc":"maklumat perubahan beransur-ansur"},"actions":{"calculate":"Kira senario","reset":"Tetapkan semula","example":"Cuba contoh","copy":"Salin hasil","result":"Keputusan senario","kilograms":"Kilogram (kg)","pounds":"Paun (lb)","dayUnit":"hari","weekUnit":"minggu","kilocalories":"kcal","perWeek":"seminggu"},"messages":{"copied":"Keputusan disalin.","copyUnavailable":"Salinan tidak tersedia dalam penyemak imbas ini.","checkInputs":"Masukkan berat semasa positif, matlamat tidak lebih tinggi daripadanya, dan defisit harian sifar atau lebih.","estimateOnly":"Senario matematik sahaja—bukan ramalan berat badan atau cadangan diet.","weightToLose":"Perbezaan berat","energyEquivalent":"Setara tenaga linear","timeline":"Garis masa linear mudah","weeklyRate":"Kadar mingguan tersirat","noDeficitChange":"Dengan defisit yang dimasukkan sifar, model ini tidak menunjukkan perubahan dan tidak boleh menganggarkan garis masa.","paceNote":"Senario linear ini melebihi kadar CDC yang sering digambarkan sebagai beransur-ansur untuk kebanyakan orang dewasa. Ia bukan sasaran yang disyorkan; tanya pakar kesihatan."},"additionalFaqs":[{"question":"Adakah ini ramalan berapa banyak berat badan saya akan turun?","answer":"Tidak. Ia menggunakan andaian tetap linear kalori-kepada-berat. NIDDK menerangkan bahawa perubahan berat badan adalah dinamik, jadi aritmetik mudah ini boleh melebih-lebihkan perubahan jangka panjang."},{"question":"Apa yang berlaku apabila defisit harian adalah sifar?","answer":"Perubahan tenaga yang dimodelkan adalah sifar, jadi halaman tidak melaporkan perubahan berat yang dimodelkan dan tiada garis masa terhingga."}]},"pl":{"copyLanguage":"pl","name":"Kalkulator scenariusza utraty wagi","title":"Kalkulator utraty wagi za darmo | UsefulVerse","description":"Poznaj prosty harmonogram celów wagowych na podstawie własnych danych wejściowych. Bezpłatna, prywatna matematyka w przeglądarce – nie plan diety ani…","intro":"Poznaj przejrzysty, uproszczony scenariusz bilansu energetycznego dla docelowej wagi. To arytmetyka, a nie przewidywanie reakcji organizmu.","howQuestion":"Jak działa ten kalkulator utraty wagi?","howAnswer":"Wprowadź aktualną wagę, niższą wagę docelową i dzienny deficyt kalorii, który już chcesz sprawdzić. Na stronie zastosowano stałe liniowe założenie dotyczące energii na masę, aby przedstawić scenariusz matematyczny. Nie zaleca deficytu kalorii, tworzenia diety ani przewidywania rzeczywistej zmiany wagi.","privacyQuestion":"Czy dane dotyczące mojej wagi zostały przesłane?","privacyAnswer":"Nie. Obliczenia działają w tej przeglądarce i wprowadzone liczby nie są wysyłane na serwer ani zapisywane przez tę stronę.","fields":{"currentWeight":"Aktualna waga","targetWeight":"Waga bramki","dailyDeficit":"Dzienny deficyt kalorii dla tego scenariusza (kcal)","unit":"Jednostka masy","methodNote":"Tylko uproszczona arytmetyka liniowa: 7700 kcal na kg lub 3500 kcal na funt. Rzeczywista zmiana masy ciała jest dynamiczna; to nie jest prognoza fizjologiczna.","healthNote":"Na tej stronie nie jest napisane co jeść i jak duży deficyt wybrać. Liczą się zdrowie, leki i indywidualne potrzeby. Przed zmianą diety lub aktywności zapytaj wykwalifikowanego pracownika służby zdrowia; nie traktuj tych szacunków jako porady lekarskiej.","sourceNiddk":"Dlaczego zmiana masy ciała jest dynamiczna:","sourceCdc":"stopniowa zmiana informacji"},"actions":{"calculate":"Oblicz scenariusz","reset":"Zresetuj","example":"Wypróbuj przykład","copy":"Skopiuj wynik","result":"Wynik scenariusza","kilograms":"Kilogramy (kg)","pounds":"Funty (funty)","dayUnit":"dni","weekUnit":"tygodnie","kilocalories":"kcal","perWeek":"tygodniowo"},"messages":{"copied":"Wynik skopiowany.","copyUnavailable":"Kopia nie jest dostępna w tej przeglądarce.","checkInputs":"Wprowadź dodatnią wagę prądu, cel nie wyższy niż ten i dzienny deficyt wynoszący zero lub więcej.","estimateOnly":"Tylko scenariusz matematyczny – nie przewidywanie masy ciała ani zalecenie diety.","weightToLose":"Różnica masy","energyEquivalent":"Liniowy odpowiednik energii","timeline":"Prosta liniowa oś czasu","weeklyRate":"Sugerowana stawka tygodniowa","noDeficitChange":"Przy zerowym deficycie model ten nie wykazuje żadnych zmian i nie można oszacować harmonogramu.","paceNote":"Ten liniowy scenariusz przewyższa tempo CDC, często opisywane przez wielu dorosłych jako stopniowe. Nie jest to zalecany cel; zapytaj pracownika służby zdrowia."},"additionalFaqs":[{"question":"Czy to jest prognoza tego, ile schudnę?","answer":"Nie. Stosuje stałe liniowe założenie dotyczące stosunku kalorii do masy. NIDDK wyjaśnia, że ​​zmiana masy ciała jest dynamiczna, zatem ta prosta arytmetyka może zawyżać długoterminowe zmiany."},{"question":"Co się stanie, gdy dzienny deficyt wyniesie zero?","answer":"Modelowana zmiana energii wynosi zero, więc strona nie zgłasza żadnych modelowanych zmian ciężaru ani skończonej osi czasu."}]},"sv":{"copyLanguage":"sv","name":"Kalkylator för viktminskningsscenario","title":"Viktminskningsräknare gratis | UsefulVerse","description":"Utforska en enkel tidslinje för viktmål utifrån dina egna inmatningar. Gratis, privat webbläsarmatematik – inte en dietplan eller förutsägelse av kroppsvikt.","intro":"Utforska ett transparent, förenklat energibalansscenario för ett viktmål. Det är aritmetik, inte en förutsägelse av hur din kropp kommer att reagera.","howQuestion":"Hur fungerar den här viktminskningskalkylatorn?","howAnswer":"Ange en aktuell vikt, en lägre målvikt och ett dagligt kaloriunderskott du redan vill undersöka. Sidan tillämpar ett fast linjärt energi-per-vikt-antagande för att visa ett matematiskt scenario. Det rekommenderar inte ett kaloriunderskott, skapa en diet eller förutsäga din faktiska viktförändring.","privacyQuestion":"Laddas mina viktuppgifter upp?","privacyAnswer":"Nej. Beräkningen körs i den här webbläsaren och de angivna siffrorna skickas inte till en server eller sparas av denna sida.","fields":{"currentWeight":"Aktuell vikt","targetWeight":"Målvikt","dailyDeficit":"Dagligt kaloriunderskott för detta scenario (kcal)","unit":"Viktenhet","methodNote":"Endast förenklad linjär aritmetik: 7 700 kcal per kg eller 3 500 kcal per lb. Verklig kroppsviktsförändring är dynamisk; detta är inte en fysiologisk prognos.","healthNote":"Den här sidan berättar inte vad du ska äta eller hur stort underskott du ska välja. Hälsa, mediciner och individuella behov har betydelse. Fråga en kvalificerad vårdpersonal innan du ändrar kost eller aktivitet; använd inte denna uppskattning som medicinsk rådgivning.","sourceNiddk":"Varför kroppsviktsförändring är dynamisk:","sourceCdc":"gradvis förändring av information"},"actions":{"calculate":"Beräkna scenario","reset":"Återställ","example":"Prova exempel","copy":"Kopiera resultat","result":"Scenarioresultat","kilograms":"Kilogram (kg)","pounds":"Pund (lb)","dayUnit":"dagar","weekUnit":"veckor","kilocalories":"kcal","perWeek":"per vecka"},"messages":{"copied":"Resultatet har kopierats.","copyUnavailable":"Kopiera är inte tillgängligt i den här webbläsaren.","checkInputs":"Ange en positiv aktuell vikt, ett mål som inte är högre än det och ett dagligt underskott på noll eller mer.","estimateOnly":"Endast matematiskt scenario - inte en kroppsviktsförutsägelse eller dietrekommendation.","weightToLose":"Viktskillnad","energyEquivalent":"Linjär energiekvivalent","timeline":"Enkel linjär tidslinje","weeklyRate":"Implicit veckopris","noDeficitChange":"Med ett inmatat underskott på noll visar denna modell ingen förändring och kan inte uppskatta en tidslinje.","paceNote":"Detta linjära scenario ligger över CDC-takten som ofta beskrivs som gradvis för många vuxna. Det är inte ett rekommenderat mål; fråga en vårdpersonal."},"additionalFaqs":[{"question":"Är detta en förutsägelse om hur mycket jag kommer att gå ner i vikt?","answer":"Nej. Den tillämpar ett fast linjärt antagande om kalori-till-vikt. NIDDK förklarar att förändringar i kroppsvikt är dynamiska, så denna enkla aritmetik kan överdriva förändringar på längre sikt."},{"question":"Vad händer när det dagliga underskottet är noll?","answer":"Den modellerade energiförändringen är noll, så sidan rapporterar ingen modellerad viktförändring och ingen ändlig tidslinje."}]},"th":{"copyLanguage":"th","name":"เครื่องคำนวณสถานการณ์การลดน้ำหนัก","title":"เครื่องคิดเลขลดน้ำหนักฟรี | UsefulVerse","description":"สำรวจไทม์ไลน์เป้าหมายน้ำหนักง่ายๆ จากข้อมูลที่คุณป้อน คณิตเบราว์เซอร์ส่วนตัวฟรี ไม่ใช่แผนการลดน้ำหนักหรือการทำนายน้ำหนักตัว","intro":"สำรวจสถานการณ์สมดุลพลังงานที่โปร่งใสและเรียบง่ายสำหรับเป้าหมายน้ำหนัก มันเป็นเลขคณิต ไม่ใช่การคาดเดาว่าร่างกายของคุณจะตอบสนองอย่างไร","howQuestion":"เครื่องคิดเลขลดน้ำหนักนี้ทำงานอย่างไร?","howAnswer":"ป้อนน้ำหนักปัจจุบัน น้ำหนักเป้าหมายที่ลดลง และการขาดดุลแคลอรี่รายวันที่คุณต้องการตรวจสอบอยู่แล้ว หน้านี้ใช้สมมติฐานพลังงานต่อน้ำหนักเชิงเส้นคงที่เพื่อแสดงสถานการณ์ทางคณิตศาสตร์ ไม่แนะนำให้มีการขาดดุลแคลอรี่ สร้างอาหาร หรือทำนายการเปลี่ยนแปลงน้ำหนักที่แท้จริงของคุณ","privacyQuestion":"มีการอัพโหลดรายละเอียดน้ำหนักของฉันหรือไม่","privacyAnswer":"ไม่ การคำนวณทำงานในเบราว์เซอร์นี้ และตัวเลขที่ป้อนจะไม่ถูกส่งไปยังเซิร์ฟเวอร์หรือบันทึกในหน้านี้","fields":{"currentWeight":"น้ำหนักปัจจุบัน","targetWeight":"น้ำหนักประตู","dailyDeficit":"การขาดดุลแคลอรี่รายวันสำหรับสถานการณ์นี้ (kcal)","unit":"หน่วยน้ำหนัก","methodNote":"เลขคณิตเชิงเส้นแบบง่ายเท่านั้น: 7,700 กิโลแคลอรีต่อกิโลกรัมหรือ 3,500 กิโลแคลอรีต่อปอนด์ การเปลี่ยนแปลงน้ำหนักตัวที่แท้จริงเป็นแบบไดนามิก นี่ไม่ใช่การพยากรณ์ทางสรีรวิทยา","healthNote":"หน้านี้ไม่ได้บอกคุณว่าจะกินอะไรหรือขาดดุลขนาดไหนให้เลือก สุขภาพ ยารักษาโรค และความต้องการของแต่ละบุคคลมีความสำคัญ สอบถามผู้เชี่ยวชาญด้านสุขภาพที่มีคุณสมบัติก่อนเปลี่ยนอาหารหรือกิจกรรม อย่าใช้ค่าประมาณนี้เป็นคำแนะนำทางการแพทย์","sourceNiddk":"ทำไมการเปลี่ยนแปลงน้ำหนักตัวจึงเป็นแบบไดนามิก:","sourceCdc":"ข้อมูลการเปลี่ยนแปลงอย่างค่อยเป็นค่อยไป"},"actions":{"calculate":"คำนวณสถานการณ์","reset":"รีเซ็ต","example":"ลองตัวอย่าง","copy":"คัดลอกผล","result":"ผลลัพธ์สถานการณ์จำลอง","kilograms":"กิโลกรัม(kg)","pounds":"ปอนด์ (ปอนด์)","dayUnit":"วัน","weekUnit":"สัปดาห์","kilocalories":"กิโลแคลอรี","perWeek":"ต่อสัปดาห์"},"messages":{"copied":"คัดลอกผลลัพธ์แล้ว","copyUnavailable":"คัดลอกไม่พร้อมใช้งานในเบราว์เซอร์นี้","checkInputs":"ป้อนน้ำหนักปัจจุบันที่เป็นบวก เป้าหมายไม่สูงกว่านั้น และการขาดดุลรายวันเป็นศูนย์หรือมากกว่า","estimateOnly":"สถานการณ์ทางคณิตศาสตร์เท่านั้น ไม่ใช่การทำนายน้ำหนักตัวหรือคำแนะนำเรื่องอาหาร","weightToLose":"ความแตกต่างน้ำหนัก","energyEquivalent":"พลังงานเชิงเส้นเทียบเท่า","timeline":"ไทม์ไลน์เชิงเส้นอย่างง่าย","weeklyRate":"อัตรารายสัปดาห์โดยนัย","noDeficitChange":"ด้วยการขาดดุลที่ป้อนเป็นศูนย์ โมเดลนี้ไม่แสดงการเปลี่ยนแปลงและไม่สามารถประมาณไทม์ไลน์ได้","paceNote":"สถานการณ์เชิงเส้นนี้อยู่เหนืออัตราก้าวของ CDC ที่มักอธิบายว่าเป็นแบบค่อยเป็นค่อยไปสำหรับผู้ใหญ่จำนวนมาก ไม่ใช่เป้าหมายที่แนะนำ ถามผู้เชี่ยวชาญด้านสุขภาพ"},"additionalFaqs":[{"question":"นี่คือการทำนายว่าฉันจะลดน้ำหนักได้เท่าไหร่?","answer":"ไม่ ใช้สมมติฐานแคลอรี่ต่อน้ำหนักเชิงเส้นคงที่ NIDDK อธิบายว่าการเปลี่ยนแปลงน้ำหนักตัวเป็นแบบไดนามิก ดังนั้นเลขคณิตอย่างง่ายนี้สามารถกล่าวเกินจริงถึงการเปลี่ยนแปลงในระยะยาวได้"},{"question":"จะเกิดอะไรขึ้นเมื่อการขาดดุลรายวันเป็นศูนย์?","answer":"การเปลี่ยนแปลงพลังงานแบบจำลองเป็นศูนย์ ดังนั้นหน้านี้จึงรายงานว่าไม่มีการเปลี่ยนแปลงน้ำหนักแบบจำลองและไม่มีไทม์ไลน์ที่จำกัด"}]},"uk":{"copyLanguage":"uk","name":"Калькулятор сценарію втрати ваги","title":"Безкоштовний калькулятор схуднення | UsefulVerse","description":"Ознайомтеся з простою хронологічною шкалою цільової ваги на основі ваших власних даних. Безкоштовна приватна математика браузера, а не план дієти чи…","intro":"Дослідіть прозорий, спрощений сценарій енергетичного балансу для цільової ваги. Це арифметика, а не прогноз того, як відреагує ваше тіло.","howQuestion":"Як працює цей калькулятор втрати ваги?","howAnswer":"Введіть поточну вагу, нижчу цільову вагу та щоденний дефіцит калорій, який ви вже хочете перевірити. На сторінці застосовано фіксоване лінійне припущення енергії на вагу, щоб показати математичний сценарій. Він не рекомендує дефіцит калорій, не створює дієту та не прогнозує вашу фактичну зміну ваги.","privacyQuestion":"Чи завантажено інформацію про мою вагу?","privacyAnswer":"Ні. Розрахунок виконується в цьому браузері, і введені числа не надсилаються на сервер і не зберігаються цією сторінкою.","fields":{"currentWeight":"Поточна вага","targetWeight":"Цільова вага","dailyDeficit":"Добовий дефіцит калорій для цього сценарію (ккал)","unit":"Одиниця ваги","methodNote":"Лише спрощена лінійна арифметика: 7700 ккал на кг або 3500 ккал на фунт. Реальна зміна маси тіла є динамічною; це не фізіологічний прогноз.","healthNote":"Ця сторінка не повідомляє вам, що їсти або який дефіцит вибрати. Здоров’я, ліки та індивідуальні потреби мають значення. Попросіть кваліфікованого медичного працівника перед тим, як змінити дієту чи діяльність; не використовуйте цю оцінку як медичну пораду.","sourceNiddk":"Чому зміна маси тіла динамічна:","sourceCdc":"інформація про поступову зміну"},"actions":{"calculate":"Розрахувати сценарій","reset":"Скинути","example":"Спробуйте приклад","copy":"Копіювати результат","result":"Результат сценарію","kilograms":"Кілограми (кг)","pounds":"Фунт (фунт)","dayUnit":"днів","weekUnit":"тижнів","kilocalories":"ккал","perWeek":"на тиждень"},"messages":{"copied":"Результат скопійовано.","copyUnavailable":"Копіювання недоступне в цьому браузері.","checkInputs":"Введіть позитивну поточну вагу, ціль не вище за неї та щоденний дефіцит нуль або більше.","estimateOnly":"Лише математичний сценарій, а не прогноз ваги тіла чи рекомендація щодо дієти.","weightToLose":"Різниця ваги","energyEquivalent":"Еквівалент лінійної енергії","timeline":"Проста лінійна шкала часу","weeklyRate":"Передбачувана тижнева ставка","noDeficitChange":"З нульовим введеним дефіцитом ця модель не показує змін і не може оцінити часову шкалу.","paceNote":"Цей лінійний сценарій перевищує швидкість CDC, яку часто описують як поступову для багатьох дорослих. Це не рекомендована ціль; запитайте медичного працівника."},"additionalFaqs":[{"question":"Це прогноз того, скільки ваги я схудну?","answer":"Ні. Застосовується фіксоване лінійне припущення про відношення калорій до ваги. NIDDK пояснює, що зміна маси тіла є динамічною, тому ця проста арифметика може перебільшити довгострокові зміни."},{"question":"Що відбувається, коли денний дефіцит дорівнює нулю?","answer":"Змодельована зміна енергії дорівнює нулю, тому сторінка не повідомляє про змодельовану зміну ваги та кінцеву часову шкалу."}]},"sw":{"copyLanguage":"sw","name":"Kikokotoo cha hali ya kupunguza uzito","title":"Kikokotoo cha kupunguza uzito bila malipo | UsefulVerse","description":"Gundua ratiba rahisi ya malengo ya uzani kutoka kwa maoni yako mwenyewe. Hesabu ya bila malipo ya kivinjari—sio mpango wa lishe au ubashiri wa uzito wa mwili.","intro":"Gundua hali ya uwazi, iliyorahisishwa ya usawa wa nishati kwa lengo la uzani. Ni hesabu, sio utabiri wa jinsi mwili wako utajibu.","howQuestion":"Je, kikokotoo hiki cha kupunguza uzito kinafanyaje kazi?","howAnswer":"Weka uzito wa sasa, uzito wa lengo la chini na nakisi ya kila siku ya kalori ambayo tayari ungependa kuchunguza. Ukurasa huu unatumia dhana isiyobadilika ya nishati-kwa-uzito ili kuonyesha hali ya hisabati. Haipendekezi upungufu wa kalori, kuunda chakula au kutabiri mabadiliko yako halisi ya uzito.","privacyQuestion":"Je, maelezo yangu ya uzito yamepakiwa?","privacyAnswer":"Hapana. Hesabu inaendeshwa katika kivinjari hiki na nambari zilizoingizwa hazitumwi kwa seva au kuhifadhiwa na ukurasa huu.","fields":{"currentWeight":"Uzito wa sasa","targetWeight":"Uzito wa lengo","dailyDeficit":"Nakisi ya kalori ya kila siku katika hali hii (kcal)","unit":"Sehemu ya uzito","methodNote":"Hesabu ya mstari iliyorahisishwa pekee: 7,700 kcal kwa kilo au 3,500 kcal kwa lb. Mabadiliko halisi ya uzito wa mwili yanabadilika; huu sio utabiri wa kisaikolojia.","healthNote":"Ukurasa huu hauambii nini cha kula au upungufu wa kuchagua. Afya, dawa na mahitaji ya mtu binafsi ni muhimu. Uliza mtaalamu wa afya aliyehitimu kabla ya kubadilisha chakula au shughuli; usitumie makadirio haya kama ushauri wa matibabu.","sourceNiddk":"Kwa nini mabadiliko ya uzito wa mwili ni ya nguvu:","sourceCdc":"habari ya mabadiliko ya taratibu"},"actions":{"calculate":"Kuhesabu hali","reset":"Weka upya","example":"Jaribu mfano","copy":"Nakili matokeo","result":"Matokeo ya mazingira","kilograms":"Kilo (kg)","pounds":"Pauni (lb)","dayUnit":"Siku za","weekUnit":"wiki","kilocalories":"kcal","perWeek":"kwa wiki"},"messages":{"copied":"Matokeo yamenakiliwa.","copyUnavailable":"Nakala haipatikani katika kivinjari hiki.","checkInputs":"Weka uzito chanya wa sasa, lengo lisilo juu kuliko hilo, na nakisi ya kila siku ya sifuri au zaidi.","estimateOnly":"Hali ya hisabati pekee—sio ubashiri wa uzito wa mwili au mapendekezo ya lishe.","weightToLose":"Tofauti ya uzito","energyEquivalent":"Nishati ya mstari sawa na","timeline":"Rahisi linear kalenda","weeklyRate":"Kiwango kilichopendekezwa cha kila wiki","noDeficitChange":"Kwa nakisi iliyoingizwa sifuri, muundo huu hauonyeshi mabadiliko yoyote na hauwezi kukadiria rekodi ya matukio.","paceNote":"Hali hii ya mstari iko juu ya kasi ya CDC ambayo mara nyingi hufafanuliwa kama ya taratibu kwa watu wazima wengi. Sio lengo lililopendekezwa; muulize mtaalamu wa afya."},"additionalFaqs":[{"question":"Je, huu ni utabiri wa ni kiasi gani cha uzito nitapunguza?","answer":"Hapana. Inatumika dhana isiyobadilika ya uzani wa kalori hadi uzani. NIDDK inaeleza kuwa mabadiliko ya uzito wa mwili yanabadilika, kwa hivyo hesabu hii rahisi inaweza kuzidisha mabadiliko ya muda mrefu."},{"question":"Nini kinatokea wakati upungufu wa kila siku ni sifuri?","answer":"Mabadiliko ya nishati ya kielelezo ni sifuri, kwa hivyo ukurasa unaripoti hakuna mabadiliko ya uzito yaliyoigwa na hakuna kalenda ya matukio yenye kikomo."}]},"mr":{"copyLanguage":"mr","name":"वजन कमी करण्याची परिस्थिती कॅल्क्युलेटर","title":"वजन कमी कॅल्क्युलेटर मोफत | UsefulVerse","description":"तुमच्या स्वत:च्या इनपुटमधून वजन-लक्ष्य टाइमलाइन एक्सप्लोर करा. विनामूल्य, खाजगी ब्राउझरचे गणित- आहार योजना किंवा शरीर-वजन अंदाज नाही.","intro":"वजनाच्या ध्येयासाठी पारदर्शक, सरलीकृत ऊर्जा-संतुलन परिस्थिती एक्सप्लोर करा. हे अंकगणित आहे, तुमचे शरीर कसे प्रतिसाद देईल याचा अंदाज नाही.","howQuestion":"हे वजन कमी करणारे कॅल्क्युलेटर कसे कार्य करते?","howAnswer":"सध्याचे वजन, कमी ध्येयाचे वजन आणि दैनंदिन कॅलरीची तूट एंटर करा जी तुम्ही आधीच तपासू इच्छित आहात. गणितीय परिस्थिती दर्शविण्यासाठी पृष्ठ एक निश्चित रेखीय ऊर्जा-प्रति-वजन गृहीतक लागू करते. हे कॅलरी कमी करण्याची शिफारस करत नाही, आहार तयार करत नाही किंवा तुमच्या वास्तविक वजन बदलाचा अंदाज लावत नाही.","privacyQuestion":"माझे वजन तपशील अपलोड केले आहेत?","privacyAnswer":"नाही. गणना या ब्राउझरमध्ये चालते आणि प्रविष्ट केलेले क्रमांक सर्व्हरवर पाठवले जात नाहीत किंवा या पृष्ठाद्वारे जतन केले जात नाहीत.","fields":{"currentWeight":"वर्तमान वजन","targetWeight":"ध्येय वजन","dailyDeficit":"या परिस्थितीसाठी दैनिक कॅलरी तूट (kcal)","unit":"वजन युनिट","methodNote":"फक्त सरलीकृत रेखीय अंकगणित: 7,700 kcal प्रति किलो किंवा 3,500 kcal प्रति lb. वास्तविक शरीर-वजन बदल डायनॅमिक आहे; हा शारीरिक अंदाज नाही.","healthNote":"हे पृष्ठ तुम्हाला काय खावे किंवा किती मोठी तूट निवडावी हे सांगत नाही. आरोग्य, औषधे आणि वैयक्तिक गरजा महत्त्वाच्या आहेत. आहार किंवा क्रियाकलाप बदलण्यापूर्वी योग्य आरोग्य व्यावसायिकांना विचारा; हा अंदाज वैद्यकीय सल्ला म्हणून वापरू नका.","sourceNiddk":"शरीर-वजन बदल डायनॅमिक का आहे:","sourceCdc":"हळूहळू-बदल माहिती"},"actions":{"calculate":"परिस्थितीची गणना करा","reset":"रीसेट करा","example":"उदाहरण वापरून पहा","copy":"निकाल कॉपी करा","result":"परिस्थिती परिणाम","kilograms":"किलोग्राम (किलो)","pounds":"पाउंड (lb)","dayUnit":"दिवस","weekUnit":"आठवडे","kilocalories":"kcal","perWeek":"दर आठवड्याला"},"messages":{"copied":"निकाल कॉपी केला.","copyUnavailable":"कॉपी या ब्राउझरमध्ये उपलब्ध नाही.","checkInputs":"सकारात्मक वर्तमान वजन, त्यापेक्षा जास्त नसलेले ध्येय आणि शून्य किंवा त्याहून अधिक दैनिक तूट प्रविष्ट करा.","estimateOnly":"केवळ गणितीय परिस्थिती - शरीर-वजन अंदाज किंवा आहार शिफारस नाही.","weightToLose":"वजनातील फरक","energyEquivalent":"रेखीय ऊर्जा समतुल्य","timeline":"साधी रेखीय टाइमलाइन","weeklyRate":"गर्भित साप्ताहिक दर","noDeficitChange":"शून्य प्रविष्ट केलेल्या तूटसह, हे मॉडेल कोणतेही बदल दर्शवत नाही आणि टाइमलाइनचा अंदाज लावू शकत नाही.","paceNote":"ही रेखीय परिस्थिती अनेक प्रौढांसाठी क्रमिक म्हणून वर्णन केलेल्या CDC गतीपेक्षा वरची आहे. हे शिफारस केलेले लक्ष्य नाही; आरोग्य व्यावसायिकांना विचारा."},"additionalFaqs":[{"question":"हे माझे वजन किती कमी होईल याचा अंदाज आहे का?","answer":"नाही. हे निश्चित रेखीय कॅलरी-ते-वजन गृहीत धरते. NIDDK स्पष्ट करते की शरीर-वजन बदल डायनॅमिक आहे, म्हणून हे साधे अंकगणित दीर्घकालीन बदल ओव्हरस्टेट करू शकते."},{"question":"जेव्हा दररोजची तूट शून्य असते तेव्हा काय होते?","answer":"मॉडेल केलेला उर्जा बदल शून्य आहे, म्हणून पृष्ठ कोणतेही मॉडेल केलेले वजन बदल आणि कोणतीही मर्यादित टाइमलाइन नोंदवत नाही."}]},"te":{"copyLanguage":"te","name":"బరువు తగ్గించే దృశ్య కాలిక్యులేటర్","title":"బరువు తగ్గించే కాలిక్యులేటర్ ఉచితం | UsefulVerse","description":"మీ స్వంత ఇన్‌పుట్‌ల నుండి ఒక సాధారణ బరువు-లక్ష కాలక్రమాన్ని అన్వేషించండి. ఉచిత, ప్రైవేట్ బ్రౌజర్ గణితం-డైట్ ప్లాన్ లేదా శరీర బరువు అంచనా కాదు.","intro":"బరువు లక్ష్యం కోసం పారదర్శక, సరళీకృత శక్తి-సమతుల్య దృష్టాంతాన్ని అన్వేషించండి. ఇది అంకగణితం, మీ శరీరం ఎలా స్పందిస్తుందో అంచనా వేయదు.","howQuestion":"ఈ బరువు తగ్గించే కాలిక్యులేటర్ ఎలా పని చేస్తుంది?","howAnswer":"మీరు ఇప్పటికే పరిశీలించాలనుకుంటున్న ప్రస్తుత బరువు, తక్కువ లక్ష్యం బరువు మరియు రోజువారీ కేలరీల లోటును నమోదు చేయండి. పేజీ గణిత దృష్టాంతాన్ని చూపించడానికి స్థిరమైన లీనియర్ ఎనర్జీ-పర్-వెయిట్ ఊహను వర్తింపజేస్తుంది. ఇది కేలరీల లోటును సిఫార్సు చేయదు, ఆహారాన్ని రూపొందించండి లేదా మీ అసలు బరువు మార్పును అంచనా వేయదు.","privacyQuestion":"నా బరువు వివరాలు అప్‌లోడ్ చేశారా?","privacyAnswer":"లేదు. గణన ఈ బ్రౌజర్‌లో నడుస్తుంది మరియు నమోదు చేసిన సంఖ్యలు సర్వర్‌కు పంపబడవు లేదా ఈ పేజీ ద్వారా సేవ్ చేయబడవు.","fields":{"currentWeight":"ప్రస్తుత బరువు","targetWeight":"గోల్ బరువు","dailyDeficit":"ఈ దృష్టాంతంలో రోజువారీ కేలరీల లోటు (kcal)","unit":"బరువు యూనిట్","methodNote":"సరళీకృత రేఖీయ అంకగణితం మాత్రమే: కిలోకు 7,700 కిలో కేలరీలు లేదా ఎల్‌బికి 3,500 కిలో కేలరీలు. నిజమైన శరీర-బరువు మార్పు డైనమిక్; ఇది శారీరక సూచన కాదు.","healthNote":"ఈ పేజీ మీకు ఏమి తినాలి లేదా ఎంత పెద్ద లోటు ఎంచుకోవాలి అని చెప్పడం లేదు. ఆరోగ్యం, మందులు మరియు వ్యక్తిగత అవసరాలు ముఖ్యమైనవి. ఆహారం లేదా కార్యాచరణను మార్చడానికి ముందు అర్హత కలిగిన ఆరోగ్య నిపుణులను అడగండి; ఈ అంచనాను వైద్య సలహాగా ఉపయోగించవద్దు.","sourceNiddk":"శరీర-బరువు మార్పు ఎందుకు డైనమిక్‌గా ఉంటుంది:","sourceCdc":"క్రమంగా మార్పు సమాచారం"},"actions":{"calculate":"దృష్టాంతాన్ని లెక్కించండి","reset":"రీసెట్ చేయండి","example":"ఉదాహరణ ప్రయత్నించండి","copy":"ఫలితాన్ని కాపీ చేయండి","result":"దృశ్య ఫలితం","kilograms":"కిలోగ్రాములు (కిలోలు)","pounds":"పౌండ్లు (lb)","dayUnit":"రోజులు","weekUnit":"వారాలు","kilocalories":"kcal","perWeek":"వారానికి"},"messages":{"copied":"ఫలితం కాపీ చేయబడింది.","copyUnavailable":"ఈ బ్రౌజర్‌లో కాపీ అందుబాటులో లేదు.","checkInputs":"సానుకూల కరెంట్ బరువు, దాని కంటే ఎక్కువ లక్ష్యం మరియు సున్నా లేదా అంతకంటే ఎక్కువ రోజువారీ లోటును నమోదు చేయండి.","estimateOnly":"గణిత దృశ్యం మాత్రమే-శరీర-బరువు అంచనా లేదా ఆహారం సిఫార్సు కాదు.","weightToLose":"బరువు వ్యత్యాసం","energyEquivalent":"లీనియర్ ఎనర్జీకి సమానమైన","timeline":"సాధారణ లీనియర్ టైమ్‌లైన్","weeklyRate":"సూచించిన వారపు రేటు","noDeficitChange":"సున్నా నమోదు చేసిన లోటుతో, ఈ మోడల్ ఎటువంటి మార్పును చూపదు మరియు కాలక్రమాన్ని అంచనా వేయదు.","paceNote":"ఈ సరళ దృశ్యం CDC వేగం కంటే ఎక్కువగా ఉంటుంది, ఇది చాలా మంది పెద్దలకు క్రమంగా వివరించబడుతుంది. ఇది సిఫార్సు చేయబడిన లక్ష్యం కాదు; ఆరోగ్య నిపుణులను అడగండి."},"additionalFaqs":[{"question":"నేను ఎంత బరువు తగ్గుతాను అనే అంచనా ఇదేనా?","answer":"సంఖ్య. ఇది స్థిరమైన లీనియర్ క్యాలరీ-టు-వెయిట్ ఊహను వర్తింపజేస్తుంది. శరీర-బరువు మార్పు డైనమిక్ అని NIDDK వివరిస్తుంది, కాబట్టి ఈ సాధారణ అంకగణితం దీర్ఘకాలిక మార్పును అతిగా అంచనా వేయగలదు."},{"question":"రోజువారీ లోటు సున్నా అయినప్పుడు ఏమి జరుగుతుంది?","answer":"మోడల్ చేయబడిన శక్తి మార్పు సున్నా, కాబట్టి పేజీ మోడల్ చేసిన బరువు మార్పు మరియు పరిమిత కాలక్రమం ఏదీ నివేదించదు."}]},"ha":{"copyLanguage":"ha","name":"Kalkuleta yanayin asarar nauyi","title":"Calculator asarar nauyi kyauta | UsefulVerse","description":"Bincika sauƙi mai sauƙi-maƙasudin lokaci daga abubuwan shigar ku. Kyauta, lissafin burauza mai zaman kansa-ba tsarin tsarin abinci ba ko hasashen nauyin…","intro":"Bincika tabbataccen yanayin ma'auni mai sauƙi-ma'auni don maƙasudin nauyi. Yana da lissafi, ba tsinkaya na yadda jikin ku zai amsa ba. Saukewa:","howQuestion":"Ta yaya wannan lissafin asarar nauyi ke aiki? Saukewa:","howAnswer":"Shigar da nauyin na yanzu, ƙananan maƙasudin maƙasudi da ƙarancin kalori na yau da kullun da kuke son bincika. Shafin yana aiki da ƙayyadadden zato mai ƙarfi-kowa-nauyi don nuna yanayin lissafi. Ba ya ba da shawarar ƙarancin kalori, ƙirƙirar abinci ko hasashen ainihin canjin ku. Saukewa:","privacyQuestion":"An loda bayanan nauyi na? Saukewa:","privacyAnswer":"A'a. Lissafin yana gudana a cikin wannan burauzar kuma ba a aika lambobin da aka shigar zuwa uwar garken ko adana ta wannan shafin ba. Saukewa:","fields":{"currentWeight":"Nauyin","targetWeight":"Nauyin manufa","dailyDeficit":"Rashin ƙarancin kalori na yau da kullun don wannan yanayin (kcal)","unit":"Nau'in nauyi","methodNote":"Ƙirar lissafi mai sauƙi kawai: 7,700 kcal a kowace kg ko 3,500 kcal a kowace lb. Canjin nauyin jiki na gaske yana da ƙarfi; wannan ba tsinkayar ilimin lissafi bane. Saukewa:","healthNote":"Wannan shafin baya gaya muku abin da za ku ci ko girman gibin da za ku zaɓa. Lafiya, magunguna da buƙatun mutum suna da mahimmanci. Tambayi ƙwararren ƙwararren lafiya kafin canza abinci ko aiki; kar a yi amfani da wannan kimanta azaman shawarar likita. Saukewa:","sourceNiddk":"Me yasa canjin-jiki yake da ƙarfi:","sourceCdc":"bayanan canji a hankali"},"actions":{"calculate":"Yi lissafin yanayin","reset":"Sake saita","example":"Gwada misali","copy":"Kwafi sakamakon","result":"Sakamakon yanayin","kilograms":"Kilogram (kg)","pounds":"Fam (lb)","dayUnit":"Kwanaki","weekUnit":"makonni","kilocalories":"kcal","perWeek":"a kowane mako"},"messages":{"copied":"An kwafi sakamakon.","copyUnavailable":"Babu kwafi a cikin wannan burauzar.","checkInputs":"Shigar da madaidaicin nauyi na yanzu, burin da bai fi shi ba, da gibin sifili ko fiye na yau da kullun.","estimateOnly":"Halin ilimin lissafi kawai-ba tsinkayar nauyin jiki ko shawarwarin abinci ba. Saukewa:","weightToLose":"Bambancin nauyi","energyEquivalent":"Makamashin linzamin kwamfuta daidai","timeline":"Sauƙaƙan layin lokaci na layi","weeklyRate":"Matsakaicin ƙimar mako-mako","noDeficitChange":"Tare da gibin sifili da aka shigar, wannan ƙirar ba ta nuna wani canji kuma ba zai iya ƙididdige lokaci ba. Saukewa:","paceNote":"Wannan yanayin na layi yana sama da takun CDC wanda aka kwatanta da sannu-sannu ga manya da yawa. Ba manufa bace; tambayi ma'aikacin lafiya. Saukewa:"},"additionalFaqs":[{"question":"Wannan shine hasashen nawa zan yi asarar nauyi? Saukewa:","answer":"A'a. Yana aiki da tsayayyen kalori-zuwa nauyi zato. NIDDK ta yi bayanin cewa canjin-jiki yana da ƙarfi, don haka wannan ƙididdiga mai sauƙi na iya wuce gona da iri na canji na dogon lokaci. Saukewa:"},{"question":"Me zai faru idan gibin yau da kullun ya zama sifili? Saukewa:","answer":"Canjin makamashin da aka ƙirƙira ba shi da sifili, don haka shafin ya ba da rahoton cewa babu wani canji mai ƙima kuma babu ƙayyadaddun lokaci. Saukewa:"}]},"tl":{"copyLanguage":"tl","name":"Pagbabawas ng timbang scenario calculator","title":"Libre ang calculator ng pagbaba ng timbang | UsefulVerse","description":"Galugarin ang isang simpleng timeline ng weight-goal mula sa sarili mong mga input. Libre, pribadong browser math—hindi isang diet plan o body-weight…","intro":"Galugarin ang isang transparent, pinasimpleng senaryo ng balanse ng enerhiya para sa isang layunin sa timbang. Ito ay aritmetika, hindi isang hula kung paano tutugon ang iyong katawan.","howQuestion":"Paano gumagana ang weight loss calculator na ito?","howAnswer":"Maglagay ng kasalukuyang timbang, mas mababang timbang ng layunin at pang-araw-araw na calorie deficit na gusto mo nang suriin. Naglalapat ang page ng fixed linear na energy-per-weight assumption para magpakita ng mathematical scenario. Hindi ito nagrerekomenda ng calorie deficit, lumikha ng diyeta o hulaan ang iyong aktwal na pagbabago sa timbang.","privacyQuestion":"Na-upload ba ang mga detalye ng aking timbang?","privacyAnswer":"Hindi. Ang pagkalkula ay tumatakbo sa browser na ito at ang mga inilagay na numero ay hindi ipinadala sa isang server o nai-save ng pahinang ito.","fields":{"currentWeight":"Kasalukuyang timbang","targetWeight":"Layunin na timbang","dailyDeficit":"Pang-araw-araw na calorie deficit para sa sitwasyong ito (kcal)","unit":"Yunit ng timbang","methodNote":"Pinasimpleng linear arithmetic lamang: 7,700 kcal bawat kg o 3,500 kcal bawat lb. Ang tunay na pagbabago sa timbang ng katawan ay pabago-bago; ito ay hindi isang physiological forecast.","healthNote":"Hindi sinasabi sa iyo ng page na ito kung ano ang kakainin o kung gaano kalaki ang depisit na pipiliin. Mahalaga ang kalusugan, mga gamot at indibidwal na pangangailangan. Magtanong sa isang kwalipikadong propesyonal sa kalusugan bago baguhin ang diyeta o aktibidad; huwag gamitin ang pagtatantya na ito bilang medikal na payo.","sourceNiddk":"Bakit dynamic ang pagbabago sa timbang ng katawan:","sourceCdc":"unti-unting pagbabago ng impormasyon"},"actions":{"calculate":"Kalkulahin ang senaryo","reset":"I-reset ang","example":"Subukan ang halimbawa","copy":"Kopyahin ang resulta","result":"Resulta ng senaryo","kilograms":"Mga Kilogramo (kg)","pounds":"Pounds (lb)","dayUnit":"araw","weekUnit":"linggo","kilocalories":"kcal","perWeek":"bawat linggo"},"messages":{"copied":"Nakopya ang resulta.","copyUnavailable":"Hindi available ang kopya sa browser na ito.","checkInputs":"Maglagay ng positibong kasalukuyang timbang, isang layunin na hindi mas mataas kaysa dito, at isang pang-araw-araw na depisit na zero o higit pa.","estimateOnly":"Pang-matematika na senaryo lang—hindi isang hula sa timbang ng katawan o rekomendasyon sa diyeta.","weightToLose":"Pagkakaiba ng timbang","energyEquivalent":"Katumbas ng linear na enerhiya","timeline":"Simpleng linear na timeline","weeklyRate":"Ipinahiwatig na lingguhang rate","noDeficitChange":"Sa isang zero entered deficit, ang modelong ito ay nagpapakita ng walang pagbabago at hindi maaaring tantyahin ang isang timeline.","paceNote":"Ang linear na sitwasyong ito ay mas mataas sa bilis ng CDC na kadalasang inilalarawan bilang unti-unti para sa maraming nasa hustong gulang. Hindi ito inirerekomendang target; magtanong sa isang propesyonal sa kalusugan."},"additionalFaqs":[{"question":"Ito ba ay isang hula kung gaano karaming timbang ang mawawala sa akin?","answer":"Hindi. Naglalapat ito ng nakapirming linear na calorie-to-weight assumption. Ipinapaliwanag ng NIDDK na ang pagbabago sa timbang ng katawan ay pabago-bago, kaya ang simpleng aritmetika na ito ay maaaring mag-overstate ng pangmatagalang pagbabago."},{"question":"Ano ang mangyayari kapag ang pang-araw-araw na deficit ay zero?","answer":"Ang nakamodelong pagbabago sa enerhiya ay zero, kaya ang pahina ay nag-uulat ng walang modelong pagbabago sa timbang at walang may hangganang timeline."}]},"ta":{"copyLanguage":"ta","name":"எடை இழப்பு காட்சி கால்குலேட்டர்","title":"எடை இழப்பு கால்குலேட்டர் இலவசம் | UsefulVerse","description":"உங்கள் சொந்த உள்ளீடுகளிலிருந்து எளிய எடை-இலக்கு காலவரிசையை ஆராயுங்கள். இலவச, தனிப்பட்ட உலாவி கணிதம்-உணவுத் திட்டம் அல்லது உடல் எடை கணிப்பு அல்ல.","intro":"எடை இலக்குக்கான வெளிப்படையான, எளிமைப்படுத்தப்பட்ட ஆற்றல்-சமநிலைக் காட்சியை ஆராயுங்கள். இது எண்கணிதம், உங்கள் உடல் எவ்வாறு பதிலளிக்கும் என்பதற்கான கணிப்பு அல்ல.","howQuestion":"இந்த எடை இழப்பு கால்குலேட்டர் எப்படி வேலை செய்கிறது?","howAnswer":"நீங்கள் ஏற்கனவே ஆய்வு செய்ய விரும்பும் தற்போதைய எடை, குறைந்த இலக்கு எடை மற்றும் தினசரி கலோரி பற்றாக்குறை ஆகியவற்றை உள்ளிடவும். பக்கம் ஒரு கணித காட்சியைக் காட்ட ஒரு எடைக்கு ஒரு நிலையான நேரியல் ஆற்றல் அனுமானத்தைப் பயன்படுத்துகிறது. இது கலோரி பற்றாக்குறையை பரிந்துரைக்காது, உணவை உருவாக்கவும் அல்லது உங்கள் உண்மையான எடை மாற்றத்தை கணிக்கவும் இல்லை.","privacyQuestion":"எனது எடை விவரங்கள் பதிவேற்றப்பட்டதா?","privacyAnswer":"இல்லை. கணக்கீடு இந்த உலாவியில் இயங்குகிறது மற்றும் உள்ளிட்ட எண்கள் சேவையகத்திற்கு அனுப்பப்படாது அல்லது இந்தப் பக்கத்தால் சேமிக்கப்படாது.","fields":{"currentWeight":"தற்போதைய எடை","targetWeight":"இலக்கு எடை","dailyDeficit":"இந்த சூழ்நிலையில் தினசரி கலோரி பற்றாக்குறை (kcal)","unit":"எடை அலகு","methodNote":"எளிமைப்படுத்தப்பட்ட நேரியல் எண்கணிதம் மட்டும்: ஒரு கிலோவுக்கு 7,700 கிலோகலோரி அல்லது ஒரு எல்பிக்கு 3,500 கிலோகலோரி. உண்மையான உடல் எடை மாற்றம் மாறும்; இது உடலியல் முன்னறிவிப்பு அல்ல.","healthNote":"இந்தப் பக்கம் எதைச் சாப்பிட வேண்டும் அல்லது எவ்வளவு பெரிய பற்றாக்குறையைத் தேர்வு செய்ய வேண்டும் என்பதைச் சொல்லவில்லை. உடல்நலம், மருந்துகள் மற்றும் தனிப்பட்ட தேவைகள் முக்கியம். உணவு அல்லது செயல்பாட்டை மாற்றுவதற்கு முன் தகுதிவாய்ந்த சுகாதார நிபுணரிடம் கேளுங்கள்; இந்த மதிப்பீட்டை மருத்துவ ஆலோசனையாக பயன்படுத்த வேண்டாம்.","sourceNiddk":"உடல் எடை மாற்றம் ஏன் மாறும்:","sourceCdc":"படிப்படியான மாற்றம் தகவல்"},"actions":{"calculate":"காட்சியைக் கணக்கிடுங்கள்","reset":"மீட்டமை","example":"உதாரணத்தை முயற்சிக்கவும்","copy":"முடிவை நகலெடுக்கவும்","result":"காட்சி முடிவு","kilograms":"கிலோகிராம்கள் (கிலோ)","pounds":"பவுண்டுகள் (எல்பி)","dayUnit":"நாட்கள்","weekUnit":"வாரங்கள்","kilocalories":"kcal","perWeek":"வாரத்திற்கு"},"messages":{"copied":"முடிவு நகலெடுக்கப்பட்டது.","copyUnavailable":"இந்த உலாவியில் நகல் கிடைக்கவில்லை.","checkInputs":"நேர்மறை மின்னோட்ட எடையை உள்ளிடவும், அதை விட அதிகமாக இல்லாத இலக்கு மற்றும் பூஜ்ஜியம் அல்லது அதற்கு மேற்பட்ட தினசரி பற்றாக்குறை.","estimateOnly":"கணித சூழ்நிலை மட்டுமே-உடல் எடை கணிப்பு அல்லது உணவு பரிந்துரை அல்ல.","weightToLose":"எடை வேறுபாடு","energyEquivalent":"நேரியல் ஆற்றல் சமமான","timeline":"எளிய நேரியல் காலவரிசை","weeklyRate":"மறைமுகமான வாராந்திர விகிதம்","noDeficitChange":"பூஜ்ஜியம் உள்ளிடப்பட்ட பற்றாக்குறையுடன், இந்த மாதிரி எந்த மாற்றத்தையும் காட்டாது மற்றும் காலவரிசையை மதிப்பிட முடியாது.","paceNote":"இந்த நேரியல் காட்சியானது CDC வேகத்திற்கு மேல் பல பெரியவர்களுக்கு படிப்படியாக விவரிக்கப்படுகிறது. இது பரிந்துரைக்கப்பட்ட இலக்கு அல்ல; ஒரு சுகாதார நிபுணரிடம் கேளுங்கள்."},"additionalFaqs":[{"question":"நான் எவ்வளவு எடை குறைப்பேன் என்பதற்கான கணிப்பு இதுவா?","answer":"இல்லை. இது ஒரு நிலையான நேரியல் கலோரி-க்கு-எடை அனுமானத்தைப் பயன்படுத்துகிறது. NIDDK உடல்-எடை மாற்றம் மாறும் என்று விளக்குகிறது, எனவே இந்த எளிய எண்கணிதம் நீண்ட கால மாற்றத்தை மிகைப்படுத்தலாம்."},{"question":"தினசரி பற்றாக்குறை பூஜ்ஜியமாக இருக்கும்போது என்ன நடக்கும்?","answer":"மாதிரியான ஆற்றல் மாற்றம் பூஜ்ஜியமாகும், எனவே பக்கம் மாதிரியான எடை மாற்றம் மற்றும் வரையறுக்கப்பட்ட காலவரிசை எதுவும் இல்லை."}]},"fa":{"copyLanguage":"fa","name":"ماشین حساب سناریوی کاهش وزن","title":"ماشین حساب کاهش وزن رایگان | UsefulVerse","description":"یک جدول زمانی ساده هدف وزن را از ورودی های خود کاوش کنید. ریاضی رایگان و خصوصی مرورگر - نه یک برنامه غذایی یا پیش بینی وزن.","intro":"یک سناریوی شفاف و ساده شده تعادل انرژی را برای یک هدف وزنی کاوش کنید. این محاسبات است، نه پیش بینی واکنش بدن شما.","howQuestion":"این ماشین حساب کاهش وزن چگونه کار می کند؟","howAnswer":"وزن فعلی، وزن هدف کمتر و کسری کالری روزانه را که می خواهید بررسی کنید وارد کنید. این صفحه یک فرض خطی ثابت انرژی به ازای وزن را برای نمایش یک سناریوی ریاضی اعمال می کند. کمبود کالری، ایجاد رژیم غذایی یا پیش بینی تغییر وزن واقعی شما را توصیه نمی کند.","privacyQuestion":"آیا جزئیات وزن من آپلود شده است؟","privacyAnswer":"خیر. محاسبه در این مرورگر اجرا می‌شود و اعداد وارد شده به سرور ارسال نمی‌شوند یا توسط این صفحه ذخیره نمی‌شوند.","fields":{"currentWeight":"وزن فعلی","targetWeight":"وزن هدف","dailyDeficit":"کمبود کالری روزانه برای این سناریو (کیلو کالری)","unit":"واحد وزن","methodNote":"فقط محاسبات خطی ساده شده: 7700 کیلوکالری در هر کیلوگرم یا 3500 کیلوکالری در هر پوند تغییر واقعی وزن بدن پویا است. این یک پیش بینی فیزیولوژیکی نیست.","healthNote":"این صفحه به شما نمی گوید چه چیزی بخورید یا چه مقدار کسری را انتخاب کنید. بهداشت، دارو و نیازهای فردی مهم است. قبل از تغییر رژیم غذایی یا فعالیت از یک متخصص بهداشت واجد شرایط بپرسید. از این تخمین به عنوان توصیه پزشکی استفاده نکنید.","sourceNiddk":"چرا تغییر وزن بدن پویا است:","sourceCdc":"تغییر تدریجی اطلاعات"},"actions":{"calculate":"سناریو","reset":"را محاسبه کنید","example":"را بازنشانی کنید مثال","copy":"را امتحان کنید نتیجه","result":"نتیجه سناریو","kilograms":"کیلوگرم (کیلوگرم)","pounds":"پوند (پوند)","dayUnit":"روز","weekUnit":"هفته","kilocalories":"کیلو کالری","perWeek":"در هفته"},"messages":{"copied":"نتیجه کپی شد","copyUnavailable":"کپی در این مرورگر موجود نیست.","checkInputs":"وزن فعلی مثبت، هدفی که بالاتر از آن نباشد و کسری روزانه صفر یا بیشتر را وارد کنید.","estimateOnly":"فقط سناریوی ریاضی - نه پیش بینی وزن بدن یا توصیه رژیم غذایی.","weightToLose":"تفاوت وزن","energyEquivalent":"معادل انرژی خطی","timeline":"جدول زمانی خطی ساده","weeklyRate":"نرخ هفتگی ضمنی","noDeficitChange":"با کسری وارد شده صفر، این مدل تغییری نشان نمی دهد و نمی تواند یک جدول زمانی را تخمین بزند.","paceNote":"این سناریوی خطی بالاتر از سرعت CDC است که اغلب برای بسیاری از بزرگسالان تدریجی توصیف می شود. این یک هدف توصیه شده نیست. از یک متخصص بهداشت بپرسید"},"additionalFaqs":[{"question":"آیا این پیش بینی میزان کاهش وزن من است؟","answer":"خیر. یک فرض کالری به وزن خطی ثابت را اعمال می کند. NIDDK توضیح می‌دهد که تغییر وزن بدن پویا است، بنابراین این محاسبه ساده می‌تواند تغییرات طولانی‌مدت را اغراق کند."},{"question":"وقتی کسری روزانه صفر شود چه اتفاقی می افتد؟","answer":"تغییر انرژی مدل شده صفر است، بنابراین صفحه هیچ تغییر وزن مدل شده و جدول زمانی محدودی را گزارش نمی کند."}]},"am":{"copyLanguage":"am","name":"የክብደት መቀነስ ሁኔታ ማስያ","title":"የክብደት መቀነሻ ካልኩሌተር ነፃ | UsefulVerse","description":"ከእራስዎ ግብዓቶች ቀላል የክብደት-ግብ የጊዜ መስመርን ያስሱ። ነፃ፣ የግል አሳሽ ሂሳብ—የአመጋገብ እቅድ ወይም የሰውነት ክብደት ትንበያ አይደለም።","intro":"ለክብደት ግብ ግልጽ፣ ቀላል የኃይል-ሚዛን ሁኔታን ያስሱ። እሱ አርቲሜቲክ ነው እንጂ ሰውነትዎ እንዴት ምላሽ እንደሚሰጥ ትንበያ አይደለም።","howQuestion":"ይህ የክብደት መቀነስ ማስያ እንዴት ይሠራል?","howAnswer":"አሁን ያለውን ክብደት፣ ዝቅተኛ የግብ ክብደት እና ቀድሞውንም መመርመር የሚፈልጉትን የካሎሪ እጥረት ያስገቡ። ገፁ የሒሳብ ሁኔታን ለማሳየት በክብደት ቋሚ የሆነ ቀጥተኛ የኃይል ግምትን ይተገበራል። የካሎሪ ጉድለትን አይመክርም, አመጋገብ ይፍጠሩ ወይም ትክክለኛውን የክብደት ለውጥዎን ይተነብዩ.","privacyQuestion":"የእኔ የክብደት ዝርዝሮች ተሰቅለዋል?","privacyAnswer":"አይ. ስሌቱ በዚህ አሳሽ ውስጥ ይሰራል እና የገቡት ቁጥሮች ወደ አገልጋይ አይላኩም ወይም በዚህ ገጽ አይቀመጡም.","fields":{"currentWeight":"የአሁኑ ክብደት","targetWeight":"የግብ ክብደት","dailyDeficit":"ለዚህ ሁኔታ ዕለታዊ የካሎሪ እጥረት (kcal)","unit":"የክብደት አሃድ","methodNote":"ቀለል ያለ የመስመር ስሌት ብቻ: 7,700 kcal በኪሎ ወይም 3,500 kcal በአንድ ፓውንድ እውነተኛ የሰውነት ክብደት ለውጥ ተለዋዋጭ ነው; ይህ የፊዚዮሎጂ ትንበያ አይደለም.","healthNote":"ይህ ገጽ ምን እንደሚበሉ ወይም ምን ያህል ጉድለት እንደሚመርጡ አይነግርዎትም። ጤና, መድሃኒቶች እና የግለሰብ ፍላጎቶች አስፈላጊ ናቸው. አመጋገብን ወይም እንቅስቃሴን ከመቀየርዎ በፊት ብቃት ያለው የጤና ባለሙያ ይጠይቁ; ይህንን ግምት እንደ የሕክምና ምክር አይጠቀሙ.","sourceNiddk":"የሰውነት ክብደት ለውጥ ለምን ተለዋዋጭ ነው፡-","sourceCdc":"ቀስ በቀስ ለውጥ መረጃ"},"actions":{"calculate":"ሁኔታን አስላ","reset":"ዳግም አስጀምር","example":"ምሳሌ ሞክር","copy":"ውጤቱን ይቅዱ","result":"የሁኔታ ውጤት","kilograms":"ኪሎግራም (ኪግ)","pounds":"ፓውንድ (ፓውንድ)","dayUnit":"ቀናት","weekUnit":"ሳምንታት","kilocalories":"kcal","perWeek":"በሳምንት"},"messages":{"copied":"ውጤት ተቀድቷል።","copyUnavailable":"ቅጂ በዚህ አሳሽ ውስጥ አይገኝም።","checkInputs":"አወንታዊ የአሁኑን ክብደት፣ ከሱ የማይበልጥ ግብ እና ዕለታዊ የዜሮ ወይም ከዚያ በላይ ጉድለት አስገባ።","estimateOnly":"የሂሳብ ሁኔታ ብቻ—የሰውነት-ክብደት ትንበያ ወይም የአመጋገብ ምክር አይደለም።","weightToLose":"የክብደት ልዩነት","energyEquivalent":"የመስመር ኢነርጂ አቻ","timeline":"ቀላል የመስመር የጊዜ መስመር","weeklyRate":"የተጠቆመ ሳምንታዊ ተመን","noDeficitChange":"በዜሮ የገባ ጉድለት፣ ይህ ሞዴል ምንም ለውጥ አያሳይም እና የጊዜ መስመርን መገመት አይችልም።","paceNote":"ይህ ቀጥተኛ ሁኔታ ለብዙ ጎልማሶች ቀስ በቀስ ከተገለጸው የ CDC ፍጥነት በላይ ነው። የሚመከር ዒላማ አይደለም; የጤና ባለሙያ ይጠይቁ."},"additionalFaqs":[{"question":"ይህ ምን ያህል ክብደት እንደምቀንስ ትንበያ ነው?","answer":"አይደለም ቋሚ የመስመር ካሎሪ-ወደ-ክብደት ግምትን ይተገበራል። NIDDK የሰውነት ክብደት ለውጥ ተለዋዋጭ መሆኑን ያብራራል፣ ስለዚህ ይህ ቀላል አርቲሜቲክ የረጅም ጊዜ ለውጥን ሊጨምር ይችላል።"},{"question":"ዕለታዊ ጉድለት ዜሮ በሚሆንበት ጊዜ ምን ይከሰታል?","answer":"የተቀረጸው የኢነርጂ ለውጥ ዜሮ ነው፣ ስለዚህ ገጹ ምንም አይነት የክብደት ለውጥ እና ያለ ገደብ የጊዜ መስመር ሪፖርት አድርጓል።"}]},"gu":{"copyLanguage":"gu","name":"વજન ઘટાડવાનું દૃશ્ય કેલ્ક્યુલેટર","title":"વજન ઘટાડવાનું કેલ્ક્યુલેટર ફ્રી | UsefulVerse","description":"તમારા પોતાના ઇનપુટ્સમાંથી એક સરળ વજન-ધ્યેય સમયરેખાનું અન્વેષણ કરો. મફત, ખાનગી બ્રાઉઝર ગણિત - આહાર યોજના અથવા શરીર-વજન અનુમાન નથી.","intro":"વજનના ધ્યેય માટે પારદર્શક, સરળ ઊર્જા-સંતુલન દૃશ્યનું અન્વેષણ કરો. તે અંકગણિત છે, તમારું શરીર કેવી રીતે પ્રતિભાવ આપશે તેની આગાહી નથી.","howQuestion":"આ વજન ઘટાડવાનું કેલ્ક્યુલેટર કેવી રીતે કામ કરે છે?","howAnswer":"વર્તમાન વજન, નીચું ધ્યેય વજન અને દૈનિક કેલરીની ખાધ દાખલ કરો જે તમે પહેલાથી જ તપાસવા માંગો છો. ગાણિતિક દૃશ્ય બતાવવા માટે પૃષ્ઠ વજન દીઠ નિશ્ચિત રેખીય ઉર્જા ધારણા લાગુ કરે છે. તે કેલરીની ખાધ, આહાર બનાવવા અથવા તમારા વાસ્તવિક વજનમાં ફેરફારની આગાહી કરવાની ભલામણ કરતું નથી.","privacyQuestion":"શું મારા વજનની વિગતો અપલોડ કરવામાં આવી છે?","privacyAnswer":"ના. ગણતરી આ બ્રાઉઝરમાં ચાલે છે અને દાખલ કરેલ નંબરો સર્વર પર મોકલવામાં આવતા નથી અથવા આ પૃષ્ઠ દ્વારા સાચવવામાં આવતા નથી.","fields":{"currentWeight":"વર્તમાન વજન","targetWeight":"ધ્યેય વજન","dailyDeficit":"આ દૃશ્ય માટે દૈનિક કેલરીની ખાધ (kcal)","unit":"વજન એકમ","methodNote":"માત્ર સરળ રેખીય અંકગણિત: 7,700 kcal પ્રતિ કિલો અથવા 3,500 kcal પ્રતિ lb. વાસ્તવિક શરીર-વજન ફેરફાર ગતિશીલ છે; આ શારીરિક આગાહી નથી.","healthNote":"આ પૃષ્ઠ તમને જણાવતું નથી કે શું ખાવું અથવા કેટલી મોટી ખોટ પસંદ કરવી. આરોગ્ય, દવાઓ અને વ્યક્તિગત જરૂરિયાતો મહત્વપૂર્ણ છે. આહાર અથવા પ્રવૃત્તિ બદલતા પહેલા લાયક આરોગ્ય વ્યાવસાયિકને પૂછો; તબીબી સલાહ તરીકે આ અંદાજનો ઉપયોગ કરશો નહીં.","sourceNiddk":"શા માટે શરીર-વજનમાં ફેરફાર ગતિશીલ છે:","sourceCdc":"ક્રમશઃ ફેરફાર માહિતી"},"actions":{"calculate":"દૃશ્યની ગણતરી કરો","reset":"રીસેટ કરો","example":"ઉદાહરણ અજમાવો","copy":"પરિણામની નકલ કરો","result":"દૃશ્ય પરિણામ","kilograms":"કિલોગ્રામ (કિલો)","pounds":"પાઉન્ડ (lb)","dayUnit":"દિવસો","weekUnit":"અઠવાડિયા","kilocalories":"kcal","perWeek":"પ્રતિ સપ્તાહ"},"messages":{"copied":"પરિણામની નકલ કરી.","copyUnavailable":"આ બ્રાઉઝરમાં નકલ ઉપલબ્ધ નથી.","checkInputs":"સકારાત્મક વર્તમાન વજન દાખલ કરો, જે ધ્યેય તેનાથી વધારે ન હોય અને દૈનિક ખાધ શૂન્ય અથવા વધુ.","estimateOnly":"માત્ર ગાણિતિક દૃશ્ય - શરીર-વજનની આગાહી અથવા આહારની ભલામણ નહીં.","weightToLose":"વજનમાં તફાવત","energyEquivalent":"લીનિયર એનર્જી સમકક્ષ","timeline":"સરળ રેખીય સમયરેખા","weeklyRate":"ગર્ભિત સાપ્તાહિક દર","noDeficitChange":"શૂન્ય દાખલ કરેલ ખાધ સાથે, આ મોડેલ કોઈ ફેરફાર બતાવતું નથી અને સમયરેખાનો અંદાજ લગાવી શકતો નથી.","paceNote":"આ રેખીય દૃશ્ય સીડીસી ગતિથી ઉપર છે જે ઘણીવાર ઘણા પુખ્ત વયના લોકો માટે ક્રમિક તરીકે વર્ણવવામાં આવે છે. તે ભલામણ કરેલ લક્ષ્ય નથી; આરોગ્ય વ્યાવસાયિકને પૂછો."},"additionalFaqs":[{"question":"શું આ હું કેટલું વજન ગુમાવીશ તેની આગાહી છે?","answer":"ના. તે એક નિશ્ચિત રેખીય કેલરી-થી-વજન ધારણા લાગુ કરે છે. NIDDK સમજાવે છે કે શરીર-વજનમાં ફેરફાર ગતિશીલ છે, તેથી આ સરળ અંકગણિત લાંબા ગાળાના ફેરફારને વધારે પડતો દર્શાવી શકે છે."},{"question":"જ્યારે દૈનિક ખાધ શૂન્ય હોય ત્યારે શું થાય છે?","answer":"મોડેલ કરેલ ઉર્જા પરિવર્તન શૂન્ય છે, તેથી પૃષ્ઠ કોઈ મોડેલ કરેલ વજનમાં ફેરફાર અને કોઈ મર્યાદિત સમયરેખાની જાણ કરતું નથી."}]}});
